window.PAGES = window.PAGES || {};
window.PAGES["day8-theory"] = {"title": "OCI Troubleshooting, Networking & Incident Response \u2014 Day 8 | Interactive Learning Platform", "css": "\n/* ============================================================\n   DESIGN TOKENS\n   Palette: void black base, Oracle red signal, cool blue for\n   network/data concepts, amber for warnings/exam-tips.\n   Type: Space Grotesk-style geometric display (system stack),\n   Inter-style body (system stack), JetBrains-style mono for\n   code/terminal (system stack) \u2014 no external fonts/CDNs.\n   ============================================================ */\n:host{\n  --void:#08090b;\n  --panel:#101217;\n  --panel-2:#15171e;\n  --panel-glass: rgba(21,23,30,0.6);\n  --border: rgba(255,255,255,0.08);\n  --border-strong: rgba(255,255,255,0.16);\n  --text-1:#eef0f3;\n  --text-2:#a7acb8;\n  --text-3:#6b7180;\n  --red:#c74634;\n  --red-bright:#ff5a3c;\n  --red-dim: rgba(199,70,52,0.15);\n  --blue:#4f8cff;\n  --blue-dim: rgba(79,140,255,0.15);\n  --amber:#e8a33d;\n  --amber-dim: rgba(232,163,61,0.15);\n  --green:#3ec28f;\n  --green-dim: rgba(62,194,143,0.15);\n  --radius: 14px;\n  --radius-sm: 8px;\n  --font-display: \"Space Grotesk\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-body: \"Inter\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-mono: \"JetBrains Mono\",\"SF Mono\",Consolas,\"Liberation Mono\",monospace;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.5);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.35);\n}\n:host([data-theme=\"light\"]){\n  --void:#f3f2ee;\n  --panel:#ffffff;\n  --panel-2:#f7f6f2;\n  --panel-glass: rgba(255,255,255,0.7);\n  --border: rgba(10,10,10,0.08);\n  --border-strong: rgba(10,10,10,0.16);\n  --text-1:#15171c;\n  --text-2:#4b4f58;\n  --text-3:#83879160;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.12);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.08);\n}\n*{box-sizing:border-box; margin:0; padding:0;}\n@media (prefers-reduced-motion: reduce){\n  *{animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important;}\n}\n:host{scroll-behavior:smooth;}\n:host{\n  background:var(--void);\n  color:var(--text-1);\n  font-family:var(--font-body);\n  line-height:1.6;\n  -webkit-font-smoothing:antialiased;\n  overflow-x:hidden;\n  transition:background .4s ease,color .4s ease;\n}\nbody::before{\n  content:\"\";\n  position:fixed; inset:0; z-index:0; pointer-events:none;\n  background:\n    radial-gradient(ellipse 800px 500px at 15% -5%, rgba(199,70,52,0.16), transparent 60%),\n    radial-gradient(ellipse 700px 500px at 100% 20%, rgba(79,140,255,0.10), transparent 60%),\n    radial-gradient(ellipse 600px 400px at 50% 100%, rgba(199,70,52,0.08), transparent 60%);\n}\nh1,h2,h3,h4{font-family:var(--font-display); letter-spacing:-0.02em; font-weight:700; color:var(--text-1);}\ncode, .mono{font-family:var(--font-mono);}\na{color:inherit;}\n::selection{background:var(--red); color:#fff;}\n::-webkit-scrollbar{width:10px; height:10px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border-strong); border-radius:10px;}\n\n/* ---------- particles / ambient bg ---------- */\n#particles{position:fixed; inset:0; z-index:0; pointer-events:none; opacity:.5;}\n\n/* ---------- progress bar ---------- */\n#progress-bar{\n  position:fixed; top:0; left:0; height:3px; width:0%;\n  background:linear-gradient(90deg,var(--red),var(--red-bright));\n  z-index:9999; box-shadow:0 0 12px var(--red-bright);\n  transition:width .1s linear;\n}\n\n/* ---------- top bar ---------- */\n#topbar{\n  position:fixed; top:0; left:0; right:0; z-index:900;\n  height:60px; display:flex; align-items:center; gap:14px;\n  padding:0 18px; margin-top:3px;\n  background:var(--panel-glass); backdrop-filter:blur(16px) saturate(140%);\n  border-bottom:1px solid var(--border);\n}\n#topbar .brand{display:flex; align-items:center; gap:10px; font-family:var(--font-display); font-weight:700; font-size:15px; white-space:nowrap;}\n#topbar .brand .dot{width:10px; height:10px; border-radius:3px; background:linear-gradient(135deg,var(--red),var(--red-bright)); box-shadow:0 0 14px var(--red-bright);}\n#sidebar-toggle{\n  background:transparent; border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:var(--radius-sm); cursor:pointer; font-size:16px;\n  display:flex; align-items:center; justify-content:center; transition:.2s;\n}\n#sidebar-toggle:hover{border-color:var(--border-strong); color:var(--text-1);}\n#search-wrap{position:relative; flex:1; max-width:420px;}\n#search{\n  width:100%; background:var(--panel); border:1px solid var(--border); color:var(--text-1);\n  padding:8px 14px 8px 34px; border-radius:999px; font-size:13px; font-family:var(--font-body);\n  outline:none; transition:.2s;\n}\n#search:focus{border-color:var(--red); box-shadow:0 0 0 3px var(--red-dim);}\n#search-wrap svg{position:absolute; left:12px; top:50%; transform:translateY(-50%); width:14px; height:14px; color:var(--text-3);}\n#search-results{\n  position:absolute; top:calc(100% + 8px); left:0; right:0; background:var(--panel);\n  border:1px solid var(--border-strong); border-radius:var(--radius-sm); box-shadow:var(--shadow-lg);\n  max-height:320px; overflow-y:auto; display:none; z-index:50;\n}\n#search-results a{display:block; padding:9px 14px; font-size:13px; color:var(--text-2); border-bottom:1px solid var(--border);}\n#search-results a:hover{background:var(--panel-2); color:var(--text-1);}\n#search-results .sr-cat{font-size:10px; text-transform:uppercase; letter-spacing:.08em; color:var(--red-bright); display:block; margin-bottom:2px;}\n\n.topbar-spacer{flex:1;}\n#theme-toggle{\n  background:var(--panel); border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:999px; cursor:pointer; display:flex; align-items:center; justify-content:center;\n  transition:.2s; font-size:15px;\n}\n#theme-toggle:hover{border-color:var(--red); color:var(--red-bright);}\n#score-chip{\n  display:flex; align-items:center; gap:6px; background:var(--panel); border:1px solid var(--border);\n  padding:6px 12px; border-radius:999px; font-size:12px; color:var(--text-2); white-space:nowrap;\n}\n#score-chip b{color:var(--red-bright); font-family:var(--font-display);}\n\n/* ---------- layout ---------- */\n#shell{display:flex; padding-top:63px; position:relative; z-index:1;}\n#sidebar{\n  width:270px; flex-shrink:0; height:calc(100% - 63px); position:sticky; top:63px;\n  overflow-y:auto; border-right:1px solid var(--border); padding:18px 10px 60px;\n  transition:margin-left .3s ease, opacity .3s ease;\n}\n#sidebar.collapsed{margin-left:-270px; opacity:0;}\n#sidebar .nav-group{margin-bottom:4px;}\n#sidebar .nav-head{\n  font-size:10px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);\n  padding:14px 12px 6px; font-weight:700;\n}\n#sidebar a.nav-link{\n  display:flex; align-items:center; gap:9px; padding:8px 12px; border-radius:var(--radius-sm);\n  font-size:13.5px; color:var(--text-2); text-decoration:none; transition:.15s; border-left:2px solid transparent;\n}\n#sidebar a.nav-link:hover{background:var(--panel); color:var(--text-1);}\n#sidebar a.nav-link.active{background:var(--red-dim); color:var(--red-bright); border-left-color:var(--red-bright); font-weight:600;}\n#sidebar a.nav-link .num{font-family:var(--font-mono); font-size:10px; color:var(--text-3); width:18px;}\n\nmain{flex:1; min-width:0; padding:0 0 100px;}\n.container{max-width:980px; margin:0 auto; padding:0 32px;}\n\n/* ---------- hero ---------- */\n#hero{position:relative; padding:100px 32px 70px; overflow:hidden; text-align:left;}\n#hero .eyebrow{\n  display:inline-flex; align-items:center; gap:8px; font-size:12px; letter-spacing:.1em; text-transform:uppercase;\n  color:var(--red-bright); background:var(--red-dim); border:1px solid rgba(199,70,52,0.3);\n  padding:6px 14px; border-radius:999px; margin-bottom:22px; font-weight:600;\n}\n#hero h1{font-size:clamp(2.4rem,5vw,4.2rem); line-height:1.02; max-width:820px;}\n#hero h1 .accent{background:linear-gradient(135deg,var(--red),var(--red-bright)); -webkit-background-clip:text; background-clip:text; color:transparent;}\n#hero p.lede{max-width:620px; font-size:17px; color:var(--text-2); margin-top:22px;}\n#hero .hero-stats{display:flex; gap:34px; margin-top:40px; flex-wrap:wrap;}\n#hero .hstat b{font-family:var(--font-display); font-size:26px; display:block;}\n#hero .hstat span{font-size:12px; color:var(--text-3); text-transform:uppercase; letter-spacing:.06em;}\n#hero .cta-row{display:flex; gap:14px; margin-top:38px; flex-wrap:wrap;}\n.btn{\n  font-family:var(--font-body); font-weight:600; font-size:14px; padding:12px 22px; border-radius:999px;\n  border:1px solid var(--border-strong); cursor:pointer; transition:.2s; display:inline-flex; align-items:center; gap:8px;\n}\n.btn-primary{background:linear-gradient(135deg,var(--red),var(--red-bright)); color:#fff; border:none; box-shadow:0 8px 24px rgba(199,70,52,0.35);}\n.btn-primary:hover{transform:translateY(-2px); box-shadow:0 12px 30px rgba(199,70,52,0.45);}\n.btn-ghost{background:var(--panel); color:var(--text-1);}\n.btn-ghost:hover{border-color:var(--red); color:var(--red-bright);}\n\n/* orbiting node animation in hero */\n#hero-orbit{position:absolute; right:-60px; top:40px; width:420px; height:420px; opacity:.9; pointer-events:none;}\n@media (max-width:1100px){#hero-orbit{display:none;}}\n\n/* ---------- sections ---------- */\nsection.chapter{padding:70px 0 10px; border-top:1px solid var(--border); scroll-margin-top:80px;}\nsection.chapter:first-of-type{border-top:none;}\n.chapter-kicker{display:flex; align-items:center; gap:10px; margin-bottom:14px;}\n.chapter-kicker .idx{\n  font-family:var(--font-mono); font-size:12px; color:var(--red-bright); background:var(--red-dim);\n  padding:4px 10px; border-radius:6px; border:1px solid rgba(199,70,52,.3);\n}\n.chapter-kicker .track{font-size:11px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);}\n.chapter h2{font-size:clamp(1.6rem,3vw,2.3rem); margin-bottom:6px;}\n.chapter .dek{color:var(--text-2); font-size:15.5px; max-width:680px; margin-bottom:30px;}\n.chapter h3{font-size:1.15rem; margin:34px 0 14px;}\n.chapter p{color:var(--text-2); font-size:15px; margin-bottom:14px; max-width:720px;}\n.chapter ul, .chapter ol{color:var(--text-2); font-size:15px; margin:0 0 16px 20px;}\n.chapter li{margin-bottom:6px;}\n.chapter strong{color:var(--text-1);}\n\n/* scroll reveal */\n.reveal{opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease;}\n.reveal.in{opacity:1; transform:translateY(0);}\n\n/* ---------- cards / panels ---------- */\n.panel{\n  background:linear-gradient(180deg,var(--panel),var(--panel-2));\n  border:1px solid var(--border); border-radius:var(--radius); padding:24px;\n  box-shadow:var(--shadow-sm); position:relative;\n}\n.panel-glow{position:relative; overflow:hidden;}\n.panel-glow::before{\n  content:\"\"; position:absolute; inset:-2px; z-index:-1; border-radius:inherit;\n  background:conic-gradient(from 180deg, var(--red), transparent 30%, var(--blue), transparent 70%, var(--red));\n  opacity:0; transition:opacity .4s;\n}\n.panel-glow:hover::before{opacity:.5;}\n.panel-glow > .panel-inner{background:var(--panel); border-radius:calc(var(--radius) - 1px); height:100%; padding:22px;}\n\n.grid{display:grid; gap:16px;}\n.grid-2{grid-template-columns:1fr 1fr;}\n.grid-3{grid-template-columns:repeat(3,1fr);}\n.grid-4{grid-template-columns:repeat(4,1fr);}\n@media (max-width:800px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr;}}\n\n.card{\n  background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm);\n  padding:18px; transition:.25s; cursor:default;\n}\n.card:hover{border-color:var(--border-strong); transform:translateY(-3px); box-shadow:var(--shadow-sm);}\n.card h4{font-size:14px; margin-bottom:8px; display:flex; align-items:center; gap:8px;}\n.card p{font-size:13.5px; margin:0; color:var(--text-2);}\n.card .tag{font-size:10px; text-transform:uppercase; letter-spacing:.06em; color:var(--red-bright); background:var(--red-dim); padding:3px 8px; border-radius:6px; margin-bottom:8px; display:inline-block;}\n\n/* ---------- callouts ---------- */\n.callout{border-radius:var(--radius-sm); padding:14px 16px; margin:16px 0; border:1px solid; font-size:14px; display:flex; gap:12px; align-items:flex-start;}\n.callout .ic{font-size:16px; flex-shrink:0; margin-top:1px;}\n.callout-tip{background:var(--green-dim); border-color:rgba(62,194,143,.35); color:var(--text-1);}\n.callout-warn{background:var(--amber-dim); border-color:rgba(232,163,61,.35); color:var(--text-1);}\n.callout-trap{background:var(--red-dim); border-color:rgba(199,70,52,.35); color:var(--text-1);}\n.callout-q{background:var(--blue-dim); border-color:rgba(79,140,255,.35); color:var(--text-1);}\n.callout b{display:block; font-size:11px; text-transform:uppercase; letter-spacing:.06em; margin-bottom:3px;}\n\n/* ---------- tables ---------- */\ntable.cmp{width:100%; border-collapse:collapse; font-size:13.5px; margin:18px 0;}\ntable.cmp th{text-align:left; color:var(--text-3); font-size:11px; text-transform:uppercase; letter-spacing:.06em; padding:10px 12px; border-bottom:1px solid var(--border-strong);}\ntable.cmp td{padding:12px; border-bottom:1px solid var(--border); color:var(--text-2);}\ntable.cmp tr:hover td{background:var(--panel);}\ntable.cmp td:first-child, table.cmp th:first-child{color:var(--text-1); font-weight:600;}\n\n/* ---------- buttons small ---------- */\n.chip-btn{\n  background:var(--panel-2); border:1px solid var(--border); color:var(--text-2); font-size:12.5px;\n  padding:7px 14px; border-radius:999px; cursor:pointer; transition:.2s; font-family:var(--font-body); font-weight:600;\n}\n.chip-btn:hover{border-color:var(--red); color:var(--red-bright);}\n.chip-btn.active{background:var(--red); color:#fff; border-color:var(--red);}\n.chip-btn:disabled{opacity:.4; cursor:not-allowed;}\n\n/* end of part1 */\n\n\n.vm-sim{display:grid; grid-template-columns:280px 1fr; gap:20px;}\n@media (max-width:800px){.vm-sim{grid-template-columns:1fr;}}\n.vm-controls{display:flex; flex-direction:column; gap:10px;}\n.vm-controls label{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--text-3); margin-top:6px;}\n.vm-controls input[type=range]{width:100%; accent-color:var(--red);}\n.host-box{border:1px dashed var(--border-strong); border-radius:var(--radius-sm); padding:16px; position:relative; background:repeating-linear-gradient(135deg, rgba(255,255,255,0.015) 0 10px, transparent 10px 20px);}\n.host-meter{display:flex; justify-content:space-between; font-size:11px; color:var(--text-3); margin-bottom:6px;}\n.meter-bar{height:8px; border-radius:6px; background:var(--panel-2); overflow:hidden; margin-bottom:14px;}\n.meter-fill{height:100%; border-radius:6px; transition:width .4s ease; background:linear-gradient(90deg,var(--blue),#7db2ff);}\n.meter-fill.cpu{background:linear-gradient(90deg,var(--red),var(--red-bright));}\n.vm-list{display:flex; flex-wrap:wrap; gap:10px; min-height:60px;}\n.vm-card{width:110px; background:var(--panel); border:1px solid var(--border-strong); border-radius:10px; padding:10px; font-size:11px; animation:popIn .3s ease; position:relative;}\n.vm-card .vm-name{font-family:var(--font-mono); color:var(--blue); font-weight:700; margin-bottom:4px;}\n.vm-card .vm-x{position:absolute; top:6px; right:8px; cursor:pointer; color:var(--text-3);}\n.vm-card .vm-x:hover{color:var(--red-bright);}\n@keyframes popIn{from{opacity:0; transform:scale(.7);} to{opacity:1; transform:scale(1);}}\n.layer-stack{display:flex; flex-direction:column; gap:6px;}\n.layer-row{display:grid; grid-template-columns:130px 1fr; gap:0; border-radius:var(--radius-sm); overflow:hidden; border:1px solid var(--border);}\n.layer-label{background:var(--panel-2); display:flex; align-items:center; justify-content:center; font-family:var(--font-display); font-weight:700; font-size:13px;}\n.layer-cells{display:grid; grid-template-columns:repeat(6,1fr);}\n.layer-cell{padding:12px 6px; text-align:center; font-size:11px; border-left:1px solid var(--border); transition:.2s; cursor:default;}\n.layer-cell.you{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.layer-cell.oracle{background:var(--blue-dim); color:var(--blue); font-weight:700;}\n.layer-cell:hover{filter:brightness(1.3);}\n.layer-legend{display:flex; gap:18px; margin-top:12px; font-size:12px; color:var(--text-2);}\n.legend-dot{width:10px; height:10px; border-radius:3px; display:inline-block; margin-right:6px; vertical-align:-1px;}\n.resp-track{position:relative; height:10px; border-radius:6px; background:linear-gradient(90deg,var(--blue) 0%,var(--blue) var(--split,50%), var(--red) var(--split,50%), var(--red) 100%); margin:30px 0 10px;}\n.resp-handle{position:absolute; top:50%; left:var(--split,50%); transform:translate(-50%,-50%); width:26px; height:26px; border-radius:50%; background:#fff; border:3px solid var(--void); cursor:grab; box-shadow:0 0 0 4px rgba(255,255,255,0.15);}\n.resp-labels{display:flex; justify-content:space-between; font-size:12px; color:var(--text-2); margin-bottom:4px;}\n.resp-layers{display:flex; flex-direction:column; gap:8px; margin-top:20px;}\n.resp-layer-row{display:flex; align-items:center; gap:12px; font-size:13px;}\n.resp-layer-row .name{width:150px; flex-shrink:0; color:var(--text-1); font-weight:600;}\n.resp-layer-row .who{font-family:var(--font-mono); font-size:11px; padding:4px 10px; border-radius:6px;}\n.who-oracle{background:var(--blue-dim); color:var(--blue);}\n.who-you{background:var(--red-dim); color:var(--red-bright);}\n.who-shared{background:var(--amber-dim); color:var(--amber);}\n.map-wrap{display:grid; grid-template-columns:1fr 260px; gap:20px;}\n@media (max-width:800px){.map-wrap{grid-template-columns:1fr;}}\n.region-dot{cursor:pointer; transition:.2s;}\n.region-dot circle{transition:.2s;}\n.region-info{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; font-size:13px; min-height:180px;}\n.region-info h4{font-size:14px; color:var(--red-bright); margin-bottom:8px;}\n.region-info .placeholder{color:var(--text-3); font-style:italic;}\n.ad-buildings{display:flex; gap:16px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.building{width:120px; text-align:center; padding:16px 10px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); transition:.4s;}\n.building .roof{font-size:26px; margin-bottom:6px;}\n.building .b-name{font-family:var(--font-mono); font-size:12px; margin-bottom:4px;}\n.building .b-status{font-size:11px; padding:3px 8px; border-radius:6px; display:inline-block;}\n.b-status.ok{background:var(--green-dim); color:var(--green);}\n.b-status.down{background:var(--red-dim); color:var(--red-bright);}\n.building.failed{opacity:.4; filter:grayscale(1); transform:translateY(4px);}\n.building.shaking{animation:shake .4s;}\n@keyframes shake{0%,100%{transform:translateX(0);}25%{transform:translateX(-4px);}75%{transform:translateX(4px);}}\n.fd-rack{display:flex; gap:14px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.rack{width:150px; border:1px solid var(--border-strong); border-radius:8px; padding:8px; background:var(--panel);}\n.rack .rack-head{font-family:var(--font-mono); font-size:11px; text-align:center; color:var(--text-3); margin-bottom:6px;}\n.rack-slot{height:20px; border-radius:4px; background:var(--panel-2); margin-bottom:4px; font-size:9px; display:flex; align-items:center; justify-content:center; color:var(--text-3); border:1px solid var(--border);}\n.rack-slot.filled{background:var(--blue-dim); color:var(--blue); border-color:rgba(79,140,255,.4); font-weight:700;}\n.rack.dead{opacity:.35;}\n.rack.dead .rack-slot.filled{background:var(--red-dim); color:var(--red-bright);}\n.calc-grid{display:grid; grid-template-columns:1fr 1fr; gap:24px;}\n@media (max-width:800px){.calc-grid{grid-template-columns:1fr;}}\n.calc-row{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:14px;}\n.calc-row label{font-size:13px; color:var(--text-2);}\n.calc-row output{font-family:var(--font-mono); color:var(--red-bright); font-weight:700; font-size:13px;}\ncanvas#capexChart{width:100%; height:220px;}\n.cost-total{display:flex; justify-content:space-between; padding-top:14px; border-top:1px solid var(--border); margin-top:6px;}\n.cost-total b{font-family:var(--font-display); font-size:20px;}\n.policy-editor{background:#0c0d10; border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; font-family:var(--font-mono); font-size:13.5px;}\n.policy-editor textarea{width:100%; min-height:80px; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:13.5px; resize:vertical; line-height:1.7;}\n.policy-verdict{margin-top:10px; padding:10px 12px; border-radius:8px; font-size:12.5px; font-family:var(--font-body); display:none;}\n.policy-verdict.ok{display:block; background:var(--green-dim); color:var(--green);}\n.policy-verdict.bad{display:block; background:var(--red-dim); color:var(--red-bright);}\n.console-sim{border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden; background:var(--panel);}\n.console-tb{display:flex; align-items:center; gap:10px; background:var(--panel-2); padding:10px 14px; border-bottom:1px solid var(--border);}\n.console-tb .dots span{width:10px; height:10px; border-radius:50%; display:inline-block; margin-right:5px;}\n.console-body{display:flex; min-height:320px;}\n.console-nav{width:170px; border-right:1px solid var(--border); padding:12px 8px; flex-shrink:0;}\n.console-nav div{padding:8px 10px; font-size:12.5px; border-radius:6px; cursor:pointer; color:var(--text-2); margin-bottom:2px;}\n.console-nav div.active{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.console-main{flex:1; padding:16px;}\n.console-toolbar{display:flex; gap:8px; margin-bottom:14px;}\n.console-table{width:100%; font-size:12.5px; border-collapse:collapse;}\n.console-table th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px 8px; border-bottom:1px solid var(--border-strong);}\n.console-table td{padding:8px; border-bottom:1px solid var(--border); color:var(--text-2);}\n.console-table tr:hover td{background:var(--panel-2);}\n.status-pill{font-size:10px; padding:2px 8px; border-radius:20px;}\n.status-pill.active{background:var(--green-dim); color:var(--green);}\n.status-pill.deleted{background:var(--red-dim); color:var(--red-bright);}\n.mini-input{background:var(--panel-2); border:1px solid var(--border-strong); color:var(--text-1); border-radius:6px; padding:6px 10px; font-size:12.5px; font-family:var(--font-body);}\n.terminal{background:#0a0b0d; border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden;}\n.terminal-tb{background:#16171c; padding:8px 14px; font-size:11px; color:var(--text-3); font-family:var(--font-mono); border-bottom:1px solid var(--border);}\n#term-out{padding:16px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; height:280px; overflow-y:auto; white-space:pre-wrap;}\n#term-out .cmdline{color:#7db2ff;}\n#term-out .cmdline::before{content:\"$ \"; color:var(--red-bright);}\n.term-input-row{display:flex; align-items:center; gap:8px; padding:10px 16px; border-top:1px solid var(--border); font-family:var(--font-mono); font-size:12.5px;}\n.term-input-row span{color:var(--red-bright);}\n#term-input{flex:1; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:12.5px;}\n.tree{font-size:13.5px;}\n.tree ul{list-style:none; margin-left:22px; border-left:1px dashed var(--border-strong); padding-left:18px;}\n.tree li{margin:6px 0; position:relative;}\n.tree .node{display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:6px; cursor:pointer; transition:.15s;}\n.tree .node:hover{background:var(--panel-2);}\n.tree .node .ic{font-size:13px;}\n.tree .node.root{color:var(--red-bright); font-weight:700;}\n.flash-wrap{display:grid; grid-template-columns:repeat(3,1fr); gap:16px;}\n@media (max-width:800px){.flash-wrap{grid-template-columns:1fr 1fr;}}\n@media (max-width:520px){.flash-wrap{grid-template-columns:1fr;}}\n.flashcard{perspective:1000px; height:130px; cursor:pointer;}\n.flashcard .fc-inner{position:relative; width:100%; height:100%; transition:transform .5s; transform-style:preserve-3d;}\n.flashcard.flipped .fc-inner{transform:rotateY(180deg);}\n.fc-face{position:absolute; inset:0; backface-visibility:hidden; border-radius:var(--radius-sm); border:1px solid var(--border-strong); padding:14px; display:flex; align-items:center; justify-content:center; text-align:center; font-size:13px;}\n.fc-front{background:var(--panel);}\n.fc-back{background:var(--red-dim); color:var(--red-bright); transform:rotateY(180deg); font-weight:600;}\n.quiz-q{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px 20px; margin-bottom:14px;}\n.quiz-q .qtext{font-size:14.5px; font-weight:600; margin-bottom:12px;}\n.quiz-opts{display:flex; flex-direction:column; gap:8px;}\n.quiz-opt{display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:8px; border:1px solid var(--border); cursor:pointer; font-size:13.5px; color:var(--text-2); transition:.15s;}\n.quiz-opt:hover{border-color:var(--border-strong); background:var(--panel-2);}\n.quiz-opt input{accent-color:var(--red);}\n.quiz-opt.correct{border-color:var(--green); background:var(--green-dim); color:var(--green);}\n.quiz-opt.incorrect{border-color:var(--red); background:var(--red-dim); color:var(--red-bright);}\n.quiz-explain{font-size:12.5px; color:var(--text-3); margin-top:10px; display:none; padding-top:10px; border-top:1px dashed var(--border);}\n.quiz-q.answered .quiz-explain{display:block;}\n#badge-wrap{text-align:center; padding:60px 20px;}\n.badge-circle{width:150px; height:150px; border-radius:50%; margin:0 auto 20px; position:relative; background:conic-gradient(var(--red-bright) 0deg, var(--red) var(--pct,0deg), var(--panel-2) var(--pct,0deg)); display:flex; align-items:center; justify-content:center; transition:background 1s ease;}\n.badge-circle::before{content:\"\"; position:absolute; inset:10px; border-radius:50%; background:var(--void);}\n.badge-circle span{position:relative; font-family:var(--font-display); font-size:28px; font-weight:700;}\n.center{text-align:center;}\n.mt-lg{margin-top:36px;}\n.small{font-size:12px; color:var(--text-3);}\nfooter{text-align:center; padding:50px 20px; color:var(--text-3); font-size:12.5px; border-top:1px solid var(--border); margin-top:60px;}\n.toc-jump{display:flex; gap:8px; flex-wrap:wrap; margin-top:18px;}\n\n\n/* ============================================================\n   DAY 8 \u2014 ADDITIONAL WIDGET STYLES\n   (troubleshooting flowchart, incident timeline, RCA builder,\n   metrics dashboards, log explorer, SSH diagnostics, VPN/\n   FastConnect topology, BGP, flow logs, LB console, storage\n   diagnostics, live monitoring, incident simulator)\n   ============================================================ */\n\n/* --- troubleshooting flowchart / decision path --- */\n.flow-decision{background:var(--panel); border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; margin-bottom:10px;}\n.flow-decision .fd-step{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--red-bright); margin-bottom:6px;}\n.flow-decision .fd-opts{display:flex; gap:8px; flex-wrap:wrap; margin-top:10px;}\n.fd-outcome{padding:12px 14px; border-radius:8px; font-size:13px; margin-top:10px; display:none;}\n.fd-outcome.good{display:block; background:var(--green-dim); color:var(--green);}\n.fd-outcome.bad{display:block; background:var(--red-dim); color:var(--red-bright);}\n\n/* --- incident lifecycle timeline --- */\n.incident-timeline{display:flex; align-items:center; gap:6px; overflow-x:auto; padding:10px 0; flex-wrap:wrap;}\n.inc-step{flex-shrink:0; min-width:110px; text-align:center; padding:12px 8px; border-radius:8px; background:var(--panel); border:1px solid var(--border); font-size:11.5px; transition:.3s;}\n.inc-step.lit{border-color:var(--red-bright); background:var(--red-dim); color:var(--red-bright);}\n\n/* --- RCA 5 whys builder --- */\n.why-row{display:flex; gap:10px; align-items:center; margin-bottom:10px;}\n.why-row .why-num{width:26px; height:26px; border-radius:50%; background:var(--panel-2); border:1px solid var(--border-strong); display:flex; align-items:center; justify-content:center; font-size:12px; flex-shrink:0;}\n.why-row input{flex:1;}\n\n/* --- metrics dashboard --- */\n.metric-grid{display:grid; grid-template-columns:repeat(4,1fr); gap:12px;}\n@media (max-width:800px){.metric-grid{grid-template-columns:1fr 1fr;}}\n.metric-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px;}\n.metric-card .m-label{font-size:10px; text-transform:uppercase; color:var(--text-3); letter-spacing:.06em;}\n.metric-card .m-val{font-family:var(--font-display); font-size:22px; margin-top:4px;}\n.metric-card canvas{width:100%; height:50px; margin-top:8px;}\n.metric-card.alert{border-color:var(--red);}\n.metric-card.alert .m-val{color:var(--red-bright);}\n\n/* --- log explorer --- */\n.log-tabs{display:flex; gap:6px; flex-wrap:wrap; margin-bottom:10px;}\n.log-viewer{background:#0a0b0d; border-radius:8px; padding:14px; font-family:var(--font-mono); font-size:11.5px; color:#c9f7d8; height:220px; overflow-y:auto; white-space:pre-wrap;}\n.log-viewer mark{background:var(--red); color:#fff; border-radius:3px; padding:0 2px;}\n\n/* --- SSH troubleshooting simulator --- */\n.ssh-cause-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(140px,1fr)); gap:10px;}\n.ssh-cause-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:12px; text-align:center; cursor:pointer; font-size:12px; transition:.2s;}\n.ssh-cause-card:hover, .ssh-cause-card.active{border-color:var(--red);}\n\n/* --- VPN / FastConnect topology --- */\n.vpn-topo{display:flex; align-items:center; justify-content:center; gap:20px; flex-wrap:wrap; margin:20px 0;}\n.vpn-node{width:130px; text-align:center; padding:14px 8px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); font-size:11.5px; transition:.3s;}\n.vpn-node.tunnel-down{border-color:var(--red); opacity:.5;}\n.vpn-tunnel-line{flex-shrink:0; width:60px; height:2px; background:var(--border-strong); position:relative;}\n.vpn-tunnel-line.up::after{content:\"\ud83d\udd12\"; position:absolute; top:-10px; left:50%; transform:translateX(-50%); font-size:12px;}\n.vpn-tunnel-line.down{background:var(--red); }\n.vpn-tunnel-line.down::after{content:\"\u2715\"; position:absolute; top:-8px; left:50%; transform:translateX(-50%); color:var(--red-bright); font-size:12px;}\n\n/* --- BGP visualizer --- */\n.bgp-peer{display:flex; justify-content:space-between; align-items:center; padding:12px 14px; border:1px solid var(--border); border-radius:8px; margin-bottom:8px; font-size:13px;}\n.bgp-state{font-size:10px; padding:3px 10px; border-radius:20px;}\n.bgp-state.established{background:var(--green-dim); color:var(--green);}\n.bgp-state.idle{background:var(--red-dim); color:var(--red-bright);}\n.bgp-state.active{background:var(--amber-dim); color:var(--amber);}\n\n/* --- flow logs --- */\n.flowlog-row{display:flex; gap:10px; padding:6px 8px; border-bottom:1px solid var(--border); font-size:11.5px; font-family:var(--font-mono);}\n.flowlog-row.rejected{color:var(--red-bright);}\n.flowlog-row.accepted{color:var(--green);}\n.flowlog-filters{display:flex; gap:8px; margin-bottom:10px;}\n\n/* --- path analyzer --- */\n.path-hop{display:flex; align-items:center; gap:10px; padding:10px 14px; border:1px solid var(--border); border-radius:8px; margin-bottom:6px; font-size:12.5px;}\n.path-hop .hop-status{width:10px; height:10px; border-radius:50%; flex-shrink:0;}\n.path-hop.ok .hop-status{background:var(--green);}\n.path-hop.blocked .hop-status{background:var(--red-bright);}\n\n/* --- load balancer console --- */\n.lb-backend-row{display:flex; justify-content:space-between; align-items:center; padding:10px 14px; border:1px solid var(--border); border-radius:8px; margin-bottom:6px; font-size:13px;}\n.lb-health-dot{width:10px; height:10px; border-radius:50%; display:inline-block; margin-right:8px;}\n.lb-health-dot.healthy{background:var(--green);}\n.lb-health-dot.unhealthy{background:var(--red-bright);}\n.lb-health-dot.warning{background:var(--amber);}\n.http-error-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(90px,1fr)); gap:10px;}\n.http-error-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:12px; text-align:center; cursor:pointer; font-family:var(--font-display); font-weight:700; font-size:16px; transition:.2s;}\n.http-error-card:hover{border-color:var(--red);}\n\n/* --- storage diagnostics --- */\n.diag-checklist{display:flex; flex-direction:column; gap:6px;}\n.diag-check-row{display:flex; align-items:center; gap:10px; padding:8px 12px; border:1px solid var(--border); border-radius:8px; font-size:12.5px;}\n.diag-check-row .dc-status{width:16px; text-align:center;}\n\n/* --- live monitoring --- */\n.livemon-grid{display:grid; grid-template-columns:repeat(4,1fr); gap:12px;}\n@media (max-width:800px){.livemon-grid{grid-template-columns:1fr 1fr;}}\n\n/* --- multi-layer incident simulator --- */\n.layer-tab{display:flex; gap:6px; flex-wrap:wrap; margin-bottom:12px;}\n.layer-tab button.chip-btn.investigated{border-color:var(--green); color:var(--green);}\n.incident-findings{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; min-height:100px; font-size:13px;}\n\n/* --- scenario design center --- */\n.scenario-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; cursor:pointer; transition:.2s; text-align:center;}\n.scenario-card:hover{border-color:var(--red);}\n\n", "html": "\nHTMLEOF\nwc -l head.html<canvas id=\"particles\"></canvas>\n<div id=\"progress-bar\"></div>\n<div id=\"topbar\">\n  <button id=\"sidebar-toggle\" title=\"Toggle sidebar\">\u2630</button>\n  <div class=\"brand\"><span class=\"dot\"></span> OCI Troubleshooting &amp; Incident Response \u00b7 Day 8</div>\n  <div id=\"search-wrap\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n    <input id=\"search\" type=\"text\" placeholder=\"Search compute, network, LB, storage issues\u2026\" autocomplete=\"off\">\n    <div id=\"search-results\"></div>\n  </div>\n  <div class=\"topbar-spacer\"></div>\n  <div id=\"score-chip\">Quiz score: <b id=\"score-chip-val\">0/0</b></div>\n  <button id=\"theme-toggle\" title=\"Toggle theme\">\ud83c\udf19</button>\n</div>\n<div id=\"shell\">\n  <nav id=\"sidebar\">\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 1 \u00b7 Methodology</div>\n      <a class=\"nav-link\" href=\"#sec-methodology\"><span class=\"num\">01</span>Troubleshooting Methodology</a>\n      <a class=\"nav-link\" href=\"#sec-incidentlifecycle\"><span class=\"num\">02</span>Incident Lifecycle</a>\n      <a class=\"nav-link\" href=\"#sec-rca\"><span class=\"num\">03</span>Root Cause Analysis</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 2 \u00b7 Compute</div>\n      <a class=\"nav-link\" href=\"#sec-computetrouble\"><span class=\"num\">04</span>Compute Troubleshooting</a>\n      <a class=\"nav-link\" href=\"#sec-instancemetrics\"><span class=\"num\">05</span>Instance Metrics</a>\n      <a class=\"nav-link\" href=\"#sec-instancelogs\"><span class=\"num\">06</span>Instance Logs</a>\n      <a class=\"nav-link\" href=\"#sec-sshtrouble\"><span class=\"num\">07</span>SSH Troubleshooting</a>\n      <a class=\"nav-link\" href=\"#sec-serialconsole\"><span class=\"num\">08</span>Serial Console &amp; Run Commands</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 3 \u00b7 Network</div>\n      <a class=\"nav-link\" href=\"#sec-osidiag\"><span class=\"num\">09</span>OSI Layer Diagnosis</a>\n      <a class=\"nav-link\" href=\"#sec-vpn\"><span class=\"num\">10</span>Site-to-Site VPN</a>\n      <a class=\"nav-link\" href=\"#sec-fastconnect\"><span class=\"num\">11</span>FastConnect</a>\n      <a class=\"nav-link\" href=\"#sec-bgproute\"><span class=\"num\">12</span>BGP &amp; Route Table Analyzer</a>\n      <a class=\"nav-link\" href=\"#sec-flowlogs\"><span class=\"num\">13</span>Flow Logs</a>\n      <a class=\"nav-link\" href=\"#sec-pathanalyzer\"><span class=\"num\">14</span>Path Analyzer &amp; Asymmetric Routing</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 4 \u00b7 Load Balancer</div>\n      <a class=\"nav-link\" href=\"#sec-lbarch\"><span class=\"num\">15</span>Load Balancer Architecture</a>\n      <a class=\"nav-link\" href=\"#sec-healthcheck\"><span class=\"num\">16</span>Health Checks &amp; Unhealthy Backends</a>\n      <a class=\"nav-link\" href=\"#sec-ssltls\"><span class=\"num\">17</span>SSL/TLS &amp; HTTP Errors</a>\n      <a class=\"nav-link\" href=\"#sec-loadtesting\"><span class=\"num\">18</span>Load Testing</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 5 \u00b7 Storage</div>\n      <a class=\"nav-link\" href=\"#sec-blockfilestorage\"><span class=\"num\">19</span>Block &amp; File Storage</a>\n      <a class=\"nav-link\" href=\"#sec-perfanalysis\"><span class=\"num\">20</span>Performance Analysis</a>\n      <a class=\"nav-link\" href=\"#sec-objectstorage\"><span class=\"num\">21</span>Object Storage</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 6 \u00b7 Hands-On</div>\n      <a class=\"nav-link\" href=\"#sec-console8\"><span class=\"num\">22</span>Console Simulator</a>\n      <a class=\"nav-link\" href=\"#sec-livemonitoring\"><span class=\"num\">23</span>Live Monitoring Dashboard</a>\n      <a class=\"nav-link\" href=\"#sec-cli8\"><span class=\"num\">24</span>CLI Terminal</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 7-8 \u00b7 Labs &amp; Scenarios</div>\n      <a class=\"nav-link\" href=\"#sec-labs8\"><span class=\"num\">25</span>Hands-On Labs</a>\n      <a class=\"nav-link\" href=\"#sec-incidentsim\"><span class=\"num\">26</span>Multi-Layer Incident Simulator</a>\n      <a class=\"nav-link\" href=\"#sec-postincident\"><span class=\"num\">27</span>Post-Incident Review</a>\n      <a class=\"nav-link\" href=\"#sec-scenariocenter\"><span class=\"num\">28</span>Scenario Design Center</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 9 \u00b7 Certification</div>\n      <a class=\"nav-link\" href=\"#sec-cheatsheet8\"><span class=\"num\">29</span>Cheat Sheets</a>\n      <a class=\"nav-link\" href=\"#sec-flashcards8\"><span class=\"num\">30</span>Flash Cards</a>\n      <a class=\"nav-link\" href=\"#sec-quiz8\"><span class=\"num\">31</span>Certification Quiz</a>\n      <a class=\"nav-link\" href=\"#sec-cert8\"><span class=\"num\">32</span>Certificate Preview</a>\n    </div>\n  </nav>\n  <main>\n    <section id=\"hero\">\n      <span class=\"eyebrow\">\u25cf Oracle Cloud Infrastructure \u2014 Operations &amp; Troubleshooting Track</span>\n      <h1>Day 8: Something's broken.<br><span class=\"accent\">Find it. Fix it.</span></h1>\n      <p class=\"lede\">Compute, SSH, network, VPN, FastConnect, load balancer, and storage troubleshooting \u2014 plus incident response and root cause analysis, using the same dashboards a real Cloud Ops engineer would.</p>\n      <div class=\"hero-stats\">\n        <div class=\"hstat\"><b>32</b><span>Interactive sections</span></div>\n        <div class=\"hstat\"><b id=\"hero-quiz-count\">20</b><span>Certification MCQs</span></div>\n        <div class=\"hstat\"><b>13</b><span>Live simulators</span></div>\n        <div class=\"hstat\"><b id=\"hero-progress\">0%</b><span>Your progress</span></div>\n      </div>\n      <div class=\"cta-row\">\n        <a href=\"#sec-methodology\" class=\"btn btn-primary\">Start learning \u2192</a>\n        <a href=\"#sec-quiz8\" class=\"btn btn-ghost\">Jump to certification quiz</a>\n      </div>\n    </section>\n    <div class=\"container\">\n<!-- 01 TROUBLESHOOTING METHODOLOGY -->\n<section class=\"chapter reveal\" id=\"sec-methodology\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">01</span><span class=\"track\">Methodology</span></div>\n  <h2>Troubleshooting Methodology</h2>\n  <p class=\"dek\">Six repeatable steps that separate structured diagnosis from guessing.</p>\n  <div class=\"grid grid-3\">\n    <div class=\"card\"><h4>1. Identify</h4><p>What is actually broken, and for whom?</p></div>\n    <div class=\"card\"><h4>2. Isolate</h4><p>Narrow down which layer/component is responsible.</p></div>\n    <div class=\"card\"><h4>3. Diagnose</h4><p>Determine the specific root cause within that layer.</p></div>\n    <div class=\"card\"><h4>4. Resolve</h4><p>Apply the fix.</p></div>\n    <div class=\"card\"><h4>5. Validate</h4><p>Confirm the fix actually resolved the issue for the user.</p></div>\n    <div class=\"card\"><h4>6. Prevent</h4><p>Address the underlying cause so it doesn't recur.</p></div>\n  </div>\n  <h3>Incident walkthrough</h3>\n  <div class=\"panel\">\n    <p class=\"mono\" style=\"color:var(--red-bright);\">\ud83d\udea8 Alert: \"Checkout API returning 502 errors for 30% of requests.\"</p>\n    <div class=\"flow-decision mt-lg\">\n      <div class=\"fd-step\">Step 1 \u2014 What do you do first?</div>\n      <div class=\"fd-opts\">\n        <button class=\"chip-btn\" data-mstep=\"1\" data-choice=\"restart\">Immediately restart all backend servers</button>\n        <button class=\"chip-btn\" data-mstep=\"1\" data-choice=\"identify\">Check the load balancer's backend health status</button>\n      </div>\n      <div class=\"fd-outcome\" id=\"mstep-1-outcome\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- 02 INCIDENT LIFECYCLE -->\n<section class=\"chapter reveal\" id=\"sec-incidentlifecycle\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">02</span><span class=\"track\">Methodology</span></div>\n  <h2>Incident Lifecycle</h2>\n  <p class=\"dek\">Every incident, big or small, moves through the same stages.</p>\n  <div class=\"panel\">\n    <div class=\"incident-timeline\" id=\"incident-timeline\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"incident-play\">\u25b6 Animate a full incident</button></div>\n  </div>\n</section>\n\n<!-- 03 ROOT CAUSE ANALYSIS -->\n<section class=\"chapter reveal\" id=\"sec-rca\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">03</span><span class=\"track\">Methodology</span></div>\n  <h2>Root Cause Analysis</h2>\n  <p class=\"dek\">The \"5 Whys\" technique: keep asking \"why\" until you reach the actual root cause, not just a symptom.</p>\n  <div class=\"panel\">\n    <p><strong>Problem:</strong> Checkout API returned 502 errors for 30% of requests.</p>\n    <div id=\"why-builder\" class=\"mt-lg\"></div>\n    <button class=\"chip-btn active mt-lg\" id=\"why-add\">\uff0b Add another \"Why\"</button>\n  </div>\n  <div class=\"grid grid-2 mt-lg\">\n    <div class=\"card\"><h4>Fishbone (Ishikawa) Diagram</h4><p>Groups potential causes into categories (People, Process, Technology, Environment) to explore breadth before depth.</p></div>\n    <div class=\"card\"><h4>Fault Tree Analysis</h4><p>Works backward from the failure, mapping all combinations of conditions that could produce it \u2014 used for complex, multi-cause outages.</p></div>\n  </div>\n</section>\n<!-- 04 COMPUTE TROUBLESHOOTING -->\n<section class=\"chapter reveal\" id=\"sec-computetrouble\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">04</span><span class=\"track\">Compute</span></div>\n  <h2>Compute Troubleshooting</h2>\n  <p class=\"dek\">Launch a VM. This one is designed to fail \u2014 diagnose why.</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"ct-launch\">\ud83d\ude80 Launch Instance</button>\n    <div class=\"lw-boot-log\" id=\"ct-log\"></div>\n    <div class=\"cost-filters mt-lg\" id=\"ct-diag-btns\" style=\"display:none;\">\n      <button class=\"chip-btn\" data-ctdiag=\"capacity\">Capacity Error</button>\n      <button class=\"chip-btn\" data-ctdiag=\"shape\">Shape Unavailable</button>\n      <button class=\"chip-btn\" data-ctdiag=\"image\">Image Corruption</button>\n      <button class=\"chip-btn\" data-ctdiag=\"cloudinit\">Cloud-init Failure</button>\n      <button class=\"chip-btn\" data-ctdiag=\"bootvol\">Boot Volume Issue</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"ct-diag-result\"></p>\n  </div>\n</section>\n\n<!-- 05 INSTANCE METRICS -->\n<section class=\"chapter reveal\" id=\"sec-instancemetrics\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">05</span><span class=\"track\">Compute</span></div>\n  <h2>Instance Metrics</h2>\n  <p class=\"dek\">A live-feeling monitoring dashboard, exactly what you'd check first for a \"slow instance\" ticket.</p>\n  <div class=\"metric-grid\" id=\"metric-grid\"></div>\n</section>\n\n<!-- 06 INSTANCE LOGS -->\n<section class=\"chapter reveal\" id=\"sec-instancelogs\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">06</span><span class=\"track\">Compute</span></div>\n  <h2>Instance Logs</h2>\n  <p class=\"dek\">Search across boot log, console history, cloud-init log, and kernel log.</p>\n  <div class=\"panel\">\n    <div class=\"log-tabs\" id=\"log-tabs\">\n      <button class=\"chip-btn active\" data-logtab=\"boot\">Boot Log</button>\n      <button class=\"chip-btn\" data-logtab=\"console\">Console History</button>\n      <button class=\"chip-btn\" data-logtab=\"cloudinit\">Cloud-init Log</button>\n      <button class=\"chip-btn\" data-logtab=\"kernel\">Kernel Log</button>\n    </div>\n    <input class=\"mini-input\" id=\"log-search\" placeholder=\"Search logs, e.g. 'error' or 'timeout'\" style=\"width:100%; margin-bottom:10px;\">\n    <div class=\"log-viewer\" id=\"log-viewer\"></div>\n  </div>\n</section>\n\n<!-- 07 SSH TROUBLESHOOTING -->\n<section class=\"chapter reveal\" id=\"sec-sshtrouble\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">07</span><span class=\"track\">Compute</span></div>\n  <h2>SSH Troubleshooting</h2>\n  <p class=\"dek\">\"Connection refused\" or \"timed out\" can mean 8 different things. Click each possible cause to see the symptom and fix.</p>\n  <div class=\"ssh-cause-grid\" id=\"ssh-cause-grid\">\n    <div class=\"ssh-cause-card\" data-ssh=\"wrongkey\">Wrong Key</div>\n    <div class=\"ssh-cause-card\" data-ssh=\"wronguser\">Wrong User</div>\n    <div class=\"ssh-cause-card\" data-ssh=\"port22\">Port 22 Blocked</div>\n    <div class=\"ssh-cause-card\" data-ssh=\"nsg\">NSG Block</div>\n    <div class=\"ssh-cause-card\" data-ssh=\"seclist\">Security List Block</div>\n    <div class=\"ssh-cause-card\" data-ssh=\"route\">Route Issue</div>\n    <div class=\"ssh-cause-card\" data-ssh=\"nopublicip\">No Public IP</div>\n    <div class=\"ssh-cause-card\" data-ssh=\"cloudinit\">Cloud-init Failure</div>\n  </div>\n  <div class=\"panel mt-lg\" id=\"ssh-detail-panel\"><p class=\"small\">Click a cause above.</p></div>\n</section>\n\n<!-- 08 SERIAL CONSOLE & RUN COMMANDS -->\n<section class=\"chapter reveal\" id=\"sec-serialconsole\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">08</span><span class=\"track\">Compute</span></div>\n  <h2>Serial Console &amp; Run Commands</h2>\n  <p class=\"dek\">When SSH is completely unreachable, the Serial Console gives you a raw text connection to the instance \u2014 no network required.</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"serial-connect\">Connect to Serial Console</button>\n    <div class=\"lw-boot-log\" id=\"serial-log\" style=\"display:none;\"></div>\n    <div id=\"serial-fix-row\" style=\"display:none; margin-top:10px;\">\n      <button class=\"chip-btn active\" id=\"serial-fix\">Edit /etc/network config and reboot</button>\n      <p class=\"small mt-lg\" id=\"serial-fix-result\"></p>\n    </div>\n  </div>\n  <h3>Run Commands (remote diagnostics)</h3>\n  <div class=\"panel mt-lg\">\n    <select class=\"mini-input\" id=\"runcmd-select\" style=\"width:100%; margin-bottom:10px;\">\n      <option value=\"uptime\">uptime &amp; load average</option>\n      <option value=\"diskspace\">df -h (disk space)</option>\n      <option value=\"services\">systemctl status nginx</option>\n    </select>\n    <button class=\"chip-btn active\" id=\"runcmd-execute\">\u25b6 Execute on instance (no SSH needed)</button>\n    <div class=\"lw-boot-log\" id=\"runcmd-out\"></div>\n  </div>\n</section>\n<!-- 09 OSI LAYER DIAGNOSIS -->\n<section class=\"chapter reveal\" id=\"sec-osidiag\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">09</span><span class=\"track\">Network</span></div>\n  <h2>OSI Layer-by-Layer Diagnosis</h2>\n  <p class=\"dek\">Structured network troubleshooting works bottom-up (or top-down) through the OSI layers rather than guessing randomly.</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"osidiag-run\">\ud83d\udd0d Diagnose: \"Can't reach the app server\"</button>\n    <div class=\"flow-steps mt-lg\" id=\"osidiag-steps\"></div>\n    <p class=\"small mt-lg\" id=\"osidiag-result\"></p>\n  </div>\n</section>\n\n<!-- 10 SITE-TO-SITE VPN -->\n<section class=\"chapter reveal\" id=\"sec-vpn\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">10</span><span class=\"track\">Network</span></div>\n  <h2>Site-to-Site VPN</h2>\n  <p class=\"dek\">An IPSec tunnel connects your on-prem CPE to OCI's DRG, giving encrypted access into your VCN.</p>\n  <div class=\"panel\">\n    <div class=\"vpn-topo\" id=\"vpn-topo\">\n      <div class=\"vpn-node\" id=\"vpn-cpe\">\ud83c\udfe2 On-Prem CPE</div>\n      <div class=\"vpn-tunnel-line up\" id=\"vpn-tunnel1\"></div>\n      <div class=\"vpn-node\" id=\"vpn-drg\">\ud83c\udfdb DRG</div>\n      <div class=\"vpn-tunnel-line up\" id=\"vpn-tunnel2\"></div>\n      <div class=\"vpn-node\" id=\"vpn-vcn\">\ud83c\udf10 VCN</div>\n    </div>\n    <p class=\"small center\">Two tunnels are created per IPSec connection for redundancy \u2014 if one goes down, traffic fails over to the other.</p>\n  </div>\n  <h3>VPN failure lab</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"cost-filters\" id=\"vpnfail-btns\">\n      <button class=\"chip-btn active\" data-vpnfail=\"tunneldown\">Tunnel Down</button>\n      <button class=\"chip-btn\" data-vpnfail=\"sharedsecret\">Shared Secret Mismatch</button>\n      <button class=\"chip-btn\" data-vpnfail=\"routemissing\">Route Missing</button>\n      <button class=\"chip-btn\" data-vpnfail=\"ikefail\">IKE Failure</button>\n      <button class=\"chip-btn\" data-vpnfail=\"ipsecfail\">IPSec Failure</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"vpnfail-result\"></p>\n  </div>\n</section>\n\n<!-- 11 FASTCONNECT -->\n<section class=\"chapter reveal\" id=\"sec-fastconnect\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">11</span><span class=\"track\">Network</span></div>\n  <h2>FastConnect</h2>\n  <p class=\"dek\">A dedicated, private physical connection between on-prem and OCI \u2014 bypassing the public internet entirely.</p>\n  <div class=\"panel\">\n    <div class=\"vpn-topo\">\n      <div class=\"vpn-node\">\ud83c\udfe2 On-Prem Network</div>\n      <div class=\"vpn-tunnel-line up\"></div>\n      <div class=\"vpn-node\">\ud83d\udd0c Provider Cross-Connect</div>\n      <div class=\"vpn-tunnel-line up\"></div>\n      <div class=\"vpn-node\">\ud83c\udfdb DRG</div>\n      <div class=\"vpn-tunnel-line up\"></div>\n      <div class=\"vpn-node\">\ud83c\udf10 VCN</div>\n    </div>\n  </div>\n  <h3>FastConnect failure lab</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"cost-filters\" id=\"fcfail-btns\">\n      <button class=\"chip-btn active\" data-fcfail=\"provisioning\">Provisioning Error</button>\n      <button class=\"chip-btn\" data-fcfail=\"routeissue\">Route Issue</button>\n      <button class=\"chip-btn\" data-fcfail=\"bgpfail\">BGP Failure</button>\n      <button class=\"chip-btn\" data-fcfail=\"bandwidth\">Bandwidth Issue</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"fcfail-result\"></p>\n  </div>\n</section>\n\n<!-- 12 BGP & ROUTE TABLE ANALYZER -->\n<section class=\"chapter reveal\" id=\"sec-bgproute\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">12</span><span class=\"track\">Network</span></div>\n  <h2>BGP &amp; Route Table Analyzer</h2>\n  <h3>BGP session states</h3>\n  <div class=\"panel\">\n    <div id=\"bgp-peers\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"bgp-flap\">\ud83d\udca5 Simulate a BGP flap</button> <button class=\"chip-btn\" id=\"bgp-reset\">\u21ba Reset</button></div>\n  </div>\n  <h3>Route table analyzer</h3>\n  <div class=\"panel mt-lg\">\n    <table class=\"route-table-ui\" id=\"route8-table\"><thead><tr><th>Destination</th><th>Target</th></tr></thead>\n      <tbody>\n        <tr><td>10.0.0.0/16</td><td>local</td></tr>\n        <tr><td>172.16.0.0/16</td><td>DRG (on-prem)</td></tr>\n        <tr><td>0.0.0.0/0</td><td>Internet Gateway</td></tr>\n      </tbody></table>\n    <div style=\"display:flex; gap:8px; margin-top:10px;\">\n      <input class=\"mini-input\" id=\"route8-test\" placeholder=\"test destination IP, e.g. 172.16.5.9\" style=\"flex:1;\">\n      <button class=\"chip-btn active\" id=\"route8-check\">Trace route</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"route8-result\"></p>\n  </div>\n</section>\n\n<!-- 13 FLOW LOGS -->\n<section class=\"chapter reveal\" id=\"sec-flowlogs\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">13</span><span class=\"track\">Network</span></div>\n  <h2>Flow Logs</h2>\n  <p class=\"dek\">Filter VCN flow logs to see exactly which packets were accepted, rejected, or dropped \u2014 and why.</p>\n  <div class=\"panel\">\n    <div class=\"flowlog-filters\" id=\"flowlog-filters\">\n      <button class=\"chip-btn active\" data-flt=\"all\">All</button>\n      <button class=\"chip-btn\" data-flt=\"accepted\">Accepted</button>\n      <button class=\"chip-btn\" data-flt=\"rejected\">Rejected</button>\n    </div>\n    <div id=\"flowlog-list\"></div>\n  </div>\n</section>\n\n<!-- 14 PATH ANALYZER & ASYMMETRIC ROUTING -->\n<section class=\"chapter reveal\" id=\"sec-pathanalyzer\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">14</span><span class=\"track\">Network</span></div>\n  <h2>Path Analyzer &amp; Asymmetric Routing</h2>\n  <p class=\"dek\">Trace a connection hop by hop to find exactly where it breaks.</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"patha-run\">\ud83d\udd0d Trace path: client \u2192 app-vm-01</button>\n    <div id=\"patha-hops\" class=\"mt-lg\"></div>\n  </div>\n  <h3>Asymmetric routing</h3>\n  <div class=\"panel mt-lg\">\n    <p class=\"small\">Outbound traffic goes through Firewall-A; the return path comes back through Firewall-B, which has no session state for it and drops the packet.</p>\n    <button class=\"chip-btn active\" id=\"asymroute-identify\">Identify the problem</button>\n    <p class=\"small mt-lg\" id=\"asymroute-result\"></p>\n  </div>\n</section>\n<!-- 15 LOAD BALANCER ARCHITECTURE -->\n<section class=\"chapter reveal\" id=\"sec-lbarch\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">15</span><span class=\"track\">Load Balancer</span></div>\n  <h2>Load Balancer Architecture</h2>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>Listener</h4><p>Defines the protocol/port the LB accepts traffic on (e.g. HTTPS:443).</p></div>\n    <div class=\"card\"><h4>Backend Set</h4><p>A group of backend servers plus a health check policy and load-balancing algorithm.</p></div>\n    <div class=\"card\"><h4>Backend Server</h4><p>An individual compute instance (or IP) serving the actual traffic.</p></div>\n    <div class=\"card\"><h4>Health Check</h4><p>Periodic probes that determine whether a backend stays in rotation.</p></div>\n  </div>\n  <div class=\"panel mt-lg\" id=\"lb-dashboard\"></div>\n</section>\n\n<!-- 16 HEALTH CHECKS & UNHEALTHY BACKENDS -->\n<section class=\"chapter reveal\" id=\"sec-healthcheck\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">16</span><span class=\"track\">Load Balancer</span></div>\n  <h2>Health Check Simulator &amp; Unhealthy Backends</h2>\n  <div class=\"panel\">\n    <div class=\"field-row\"><label>Health check path</label><input class=\"mini-input\" id=\"hc-path\" value=\"/health\" style=\"width:100%;\"></div>\n    <div class=\"field-row\"><label>Port</label><input class=\"mini-input\" id=\"hc-port\" value=\"8080\" style=\"width:100%;\"></div>\n    <div class=\"field-row\"><label>Interval (seconds)</label><input type=\"range\" id=\"hc-interval\" min=\"5\" max=\"60\" value=\"10\" style=\"width:100%; accent-color:var(--red);\"><p class=\"small\">Interval: <strong id=\"hc-interval-val\">10s</strong></p></div>\n    <button class=\"chip-btn active\" id=\"hc-apply\">Apply &amp; check backend health</button>\n    <div id=\"lb-backends-list\" class=\"mt-lg\"></div>\n  </div>\n  <h3>Diagnose the unhealthy backend</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"cost-filters\" id=\"unhealthy-btns\">\n      <button class=\"chip-btn active\" data-uh=\"firewall\">Firewall Blocking Health Check Port</button>\n      <button class=\"chip-btn\" data-uh=\"app\">Application Not Responding on /health</button>\n      <button class=\"chip-btn\" data-uh=\"wrongport\">Health Check Using Wrong Port</button>\n      <button class=\"chip-btn\" data-uh=\"dns\">Backend DNS Resolution Failure</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"unhealthy-result\"></p>\n  </div>\n</section>\n\n<!-- 17 SSL/TLS & HTTP ERRORS -->\n<section class=\"chapter reveal\" id=\"sec-ssltls\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">17</span><span class=\"track\">Load Balancer</span></div>\n  <h2>SSL/TLS &amp; HTTP Errors</h2>\n  <div class=\"panel\">\n    <div class=\"cost-filters\" id=\"ssl-case-btns\">\n      <button class=\"chip-btn active\" data-sslcase=\"mismatch\">Certificate Mismatch</button>\n      <button class=\"chip-btn\" data-sslcase=\"expired\">Expired Certificate</button>\n      <button class=\"chip-btn\" data-sslcase=\"wrongcn\">Wrong CN/SAN</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"ssl-case-result\"></p>\n  </div>\n  <h3>HTTP error root-cause mapping</h3>\n  <div class=\"http-error-grid mt-lg\" id=\"http-error-grid\">\n    <div class=\"http-error-card\" data-code=\"400\">400</div>\n    <div class=\"http-error-card\" data-code=\"401\">401</div>\n    <div class=\"http-error-card\" data-code=\"403\">403</div>\n    <div class=\"http-error-card\" data-code=\"404\">404</div>\n    <div class=\"http-error-card\" data-code=\"500\">500</div>\n    <div class=\"http-error-card\" data-code=\"502\">502</div>\n    <div class=\"http-error-card\" data-code=\"503\">503</div>\n    <div class=\"http-error-card\" data-code=\"504\">504</div>\n  </div>\n  <div class=\"cia-detail mt-lg\" id=\"http-error-detail\">Click an error code above.</div>\n</section>\n\n<!-- 18 LOAD TESTING -->\n<section class=\"chapter reveal\" id=\"sec-loadtesting\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">18</span><span class=\"track\">Load Balancer</span></div>\n  <h2>Load Testing</h2>\n  <p class=\"dek\">Simulate a traffic spike and watch backend load and response codes shift in real time.</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"loadtest-run\">\ud83d\udcc8 Simulate 10x traffic spike</button>\n    <div class=\"metric-grid mt-lg\" id=\"loadtest-metrics\"></div>\n  </div>\n</section>\n\n<!-- 19 BLOCK & FILE STORAGE -->\n<section class=\"chapter reveal\" id=\"sec-blockfilestorage\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">19</span><span class=\"track\">Storage</span></div>\n  <h2>Block &amp; File Storage Troubleshooting</h2>\n  <h3>Block volume</h3>\n  <div class=\"panel\">\n    <div class=\"cost-filters\" id=\"bv-issue-btns\">\n      <button class=\"chip-btn active\" data-bvissue=\"attach\">Attach Failure</button>\n      <button class=\"chip-btn\" data-bvissue=\"detach\">Detach Failure</button>\n      <button class=\"chip-btn\" data-bvissue=\"perf\">Performance Issue</button>\n      <button class=\"chip-btn\" data-bvissue=\"backup\">Backup Failure</button>\n      <button class=\"chip-btn\" data-bvissue=\"restore\">Restore Failure</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"bv-issue-result\"></p>\n  </div>\n  <h3>File storage (NFS)</h3>\n  <div class=\"panel mt-lg\">\n    <p class=\"mono\" style=\"color:var(--red-bright);\">mount.nfs: Connection timed out</p>\n    <div class=\"diag-checklist mt-lg\" id=\"nfs-diag-checklist\"></div>\n    <button class=\"chip-btn active mt-lg\" id=\"nfs-diag-run\">Run diagnostics</button>\n  </div>\n</section>\n\n<!-- 20 PERFORMANCE ANALYSIS -->\n<section class=\"chapter reveal\" id=\"sec-perfanalysis\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">20</span><span class=\"track\">Storage</span></div>\n  <h2>Storage Performance Analysis</h2>\n  <p class=\"dek\">iostat-style metrics for diagnosing slow disk performance.</p>\n  <div class=\"panel\">\n    <div class=\"terminal\" style=\"max-width:100%;\"><div id=\"iostat-out\" style=\"padding:14px; font-family:var(--font-mono); font-size:11.5px; color:#c9f7d8; white-space:pre-wrap;\"></div></div>\n    <p class=\"small mt-lg\" id=\"iostat-analysis\"></p>\n  </div>\n</section>\n\n<!-- 21 OBJECT STORAGE -->\n<section class=\"chapter reveal\" id=\"sec-objectstorage\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">21</span><span class=\"track\">Storage</span></div>\n  <h2>Object Storage Troubleshooting</h2>\n  <div class=\"panel\">\n    <div class=\"cost-filters\" id=\"os-issue-btns\">\n      <button class=\"chip-btn active\" data-osissue=\"permission\">403 Permission Denied</button>\n      <button class=\"chip-btn\" data-osissue=\"lifecycle\">Objects Missing (Lifecycle Policy)</button>\n      <button class=\"chip-btn\" data-osissue=\"versioning\">Old Version Returned</button>\n      <button class=\"chip-btn\" data-osissue=\"access\">Access Failure from App</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"os-issue-result\"></p>\n  </div>\n</section>\n<!-- 22 CONSOLE SIMULATOR -->\n<section class=\"chapter reveal\" id=\"sec-console8\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">22</span><span class=\"track\">Hands-On</span></div>\n  <h2>OCI Console Simulator</h2>\n  <div class=\"console-sim\">\n    <div class=\"console-tb\"><div class=\"dots\"><span style=\"background:#ff5f57\"></span><span style=\"background:#febc2e\"></span><span style=\"background:#28c840\"></span></div><span class=\"small mono\">console.oracle-simulator.local/operations</span></div>\n    <div class=\"console-body\">\n      <div class=\"console-nav\">\n        <div class=\"active\" data-panel8=\"compute8\">\ud83d\udda5 Compute</div>\n        <div data-panel8=\"network8\">\ud83c\udf10 Networking</div>\n        <div data-panel8=\"lb8\">\u2696\ufe0f Load Balancer</div>\n        <div data-panel8=\"storage8\">\ud83d\udcbd Storage</div>\n      </div>\n      <div class=\"console-main\">\n        <div class=\"console-panel8\" id=\"panel8-compute8\">\n          <table class=\"console-table\"><thead><tr><th>Instance</th><th>State</th><th></th></tr></thead>\n          <tbody><tr><td>web-vm-01</td><td><span class=\"status-pill deleted\">Unreachable</span></td><td><button class=\"chip-btn\" id=\"c8-restart\">Restart</button></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel8\" id=\"panel8-network8\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>VCN</th><th>Status</th></tr></thead>\n          <tbody><tr><td>prod-vcn</td><td><span class=\"status-pill active\">Available</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel8\" id=\"panel8-lb8\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Load Balancer</th><th>Backend Health</th></tr></thead>\n          <tbody><tr><td>prod-lb</td><td><span class=\"status-pill deleted\">1/3 Unhealthy</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel8\" id=\"panel8-storage8\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Volume</th><th>Status</th></tr></thead>\n          <tbody><tr><td>web-vm-01-boot</td><td><span class=\"status-pill active\">Attached</span></td></tr></tbody></table>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 23 LIVE MONITORING DASHBOARD -->\n<section class=\"chapter reveal\" id=\"sec-livemonitoring\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">23</span><span class=\"track\">Hands-On</span></div>\n  <h2>Live Monitoring Dashboard</h2>\n  <div class=\"livemon-grid\" id=\"livemon-grid\"></div>\n</section>\n\n<!-- 24 CLI TERMINAL -->\n<section class=\"chapter reveal\" id=\"sec-cli8\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">24</span><span class=\"track\">Hands-On</span></div>\n  <h2>CLI Terminal</h2>\n  <div class=\"terminal\">\n    <div class=\"terminal-tb\">oci-cli \u2014 operations &amp; troubleshooting \u2014 simulator</div>\n    <div id=\"term-out8\"></div>\n    <div class=\"term-input-row\"><span>$</span><input id=\"term-input8\" type=\"text\" placeholder=\"type: help\" autocomplete=\"off\"></div>\n  </div>\n  <p class=\"small mt-lg\">Try: <span class=\"mono\">help, oci compute instance list, oci compute instance action, oci compute console-history capture, oci network vcn list, oci network ipsec list, oci network fast-connect-provider-service list, oci lb backend-health get, oci bv volume list, oci fs export list, oci logging log list, clear</span></p>\n</section>\n\n<!-- 25 HANDS-ON LABS -->\n<section class=\"chapter reveal\" id=\"sec-labs8\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">25</span><span class=\"track\">Labs &amp; Scenarios</span></div>\n  <h2>Hands-On Labs</h2>\n  <div id=\"labs8-list\"></div>\n  <p class=\"small center mt-lg\" id=\"labs8-progress\">0 / 11 labs complete</p>\n</section>\n\n<!-- 26 MULTI-LAYER INCIDENT SIMULATOR -->\n<section class=\"chapter reveal\" id=\"sec-incidentsim\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">26</span><span class=\"track\">Labs &amp; Scenarios</span></div>\n  <h2>Multi-Layer Incident Simulator</h2>\n  <p class=\"dek\"><strong>Production outage:</strong> checkout is down for all customers. Investigate each layer to find the actual root cause \u2014 most layers are red herrings.</p>\n  <div class=\"panel\">\n    <div class=\"layer-tab\" id=\"incident-layer-tabs\">\n      <button class=\"chip-btn\" data-layer=\"compute\">Compute</button>\n      <button class=\"chip-btn\" data-layer=\"network\">Network</button>\n      <button class=\"chip-btn\" data-layer=\"security\">Security</button>\n      <button class=\"chip-btn\" data-layer=\"storage\">Storage</button>\n      <button class=\"chip-btn\" data-layer=\"lb\">Load Balancer</button>\n      <button class=\"chip-btn\" data-layer=\"dns\">DNS</button>\n      <button class=\"chip-btn\" data-layer=\"application\">Application</button>\n    </div>\n    <div class=\"incident-findings\" id=\"incident-findings\">Click a layer above to investigate it.</div>\n    <button class=\"chip-btn active mt-lg\" id=\"incident-submit\" style=\"display:none;\">Submit root cause: Application</button>\n  </div>\n</section>\n\n<!-- 27 POST-INCIDENT REVIEW -->\n<section class=\"chapter reveal\" id=\"sec-postincident\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">27</span><span class=\"track\">Labs &amp; Scenarios</span></div>\n  <h2>Post-Incident Review</h2>\n  <p class=\"dek\">Generate a report from the incident you just solved.</p>\n  <div class=\"panel\" id=\"postincident-panel\">\n    <button class=\"chip-btn active\" id=\"postincident-generate\">Generate Incident Report</button>\n    <div class=\"lw-boot-log\" id=\"postincident-report\" style=\"display:none;\"></div>\n  </div>\n</section>\n\n<!-- 28 SCENARIO DESIGN CENTER -->\n<section class=\"chapter reveal\" id=\"sec-scenariocenter\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">28</span><span class=\"track\">Labs &amp; Scenarios</span></div>\n  <h2>Scenario Design Center</h2>\n  <p class=\"dek\">Pick an industry \u2014 each generates a different flavor of production outage.</p>\n  <div class=\"grid grid-3\" id=\"scenario-grid\">\n    <div class=\"scenario-card\" data-industry=\"banking\">\ud83c\udfe6 Banking</div>\n    <div class=\"scenario-card\" data-industry=\"healthcare\">\ud83c\udfe5 Healthcare</div>\n    <div class=\"scenario-card\" data-industry=\"retail\">\ud83d\uded2 Retail</div>\n    <div class=\"scenario-card\" data-industry=\"manufacturing\">\ud83c\udfed Manufacturing</div>\n    <div class=\"scenario-card\" data-industry=\"government\">\ud83c\udfdb Government</div>\n  </div>\n  <div class=\"panel mt-lg\" id=\"scenario-detail\" style=\"display:none;\"></div>\n</section>\n<!-- 29 CHEAT SHEETS -->\n<section class=\"chapter reveal\" id=\"sec-cheatsheet8\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">29</span><span class=\"track\">Certification Center</span></div>\n  <h2>Cheat Sheets</h2>\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><h4>Compute &amp; SSH</h4><ul style=\"margin-left:16px;\"><li>No SSH? Check: key, user, NSG, Security List, route, public IP, cloud-init</li><li>Serial Console works even with zero network connectivity</li><li>Run Commands execute without needing SSH at all</li></ul></div>\n    <div class=\"card\"><h4>Network</h4><ul style=\"margin-left:16px;\"><li>Diagnose bottom-up through OSI layers</li><li>2 tunnels per IPSec connection for redundancy</li><li>FastConnect = dedicated private link, bypasses the internet</li></ul></div>\n    <div class=\"card\"><h4>Load Balancer</h4><ul style=\"margin-left:16px;\"><li>502 = bad response from backend; 503 = no healthy backend; 504 = backend too slow</li><li>Unhealthy backend \u2260 application down \u2014 check firewall/port/path first</li></ul></div>\n    <div class=\"card\"><h4>Storage &amp; Incident Response</h4><ul style=\"margin-left:16px;\"><li>NFS mount timeout \u2192 check mount target NSG/Security List first</li><li>5 Whys: keep asking until you hit the real root cause, not a symptom</li><li>Always Validate + Prevent, not just Resolve</li></ul></div>\n  </div>\n  <table class=\"cmp mt-lg\"><tr><th>CLI Reference</th></tr>\n    <tr><td class=\"mono\">oci compute instance list</td></tr><tr><td class=\"mono\">oci compute instance action</td></tr>\n    <tr><td class=\"mono\">oci compute console-history capture</td></tr><tr><td class=\"mono\">oci network ipsec list</td></tr>\n    <tr><td class=\"mono\">oci network fast-connect-provider-service list</td></tr><tr><td class=\"mono\">oci lb backend-health get</td></tr>\n    <tr><td class=\"mono\">oci bv volume list</td></tr><tr><td class=\"mono\">oci fs export list</td></tr>\n    <tr><td class=\"mono\">oci logging log list</td></tr></table>\n</section>\n\n<!-- 30 FLASHCARDS -->\n<section class=\"chapter reveal\" id=\"sec-flashcards8\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">30</span><span class=\"track\">Certification Center</span></div>\n  <h2>Flash Cards</h2>\n  <div class=\"flash-wrap\" id=\"flash-wrap8\"></div>\n</section>\n\n<!-- 31 QUIZ -->\n<section class=\"chapter reveal\" id=\"sec-quiz8\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">31</span><span class=\"track\">Certification Center</span></div>\n  <h2>Certification Readiness Quiz</h2>\n  <div id=\"quiz-wrap8\"></div>\n  <div class=\"panel center mt-lg\"><p>Your score: <b id=\"quiz-final-score8\" style=\"color:var(--red-bright); font-family:var(--font-display); font-size:20px;\">0 / 20</b></p></div>\n</section>\n\n<!-- 32 CERTIFICATE -->\n<section class=\"chapter reveal\" id=\"sec-cert8\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">32</span><span class=\"track\">Certification Center</span></div>\n  <h2>Completion &amp; Certificate Preview</h2>\n  <div class=\"center\" style=\"padding:20px 0 40px;\">\n    <div class=\"badge-circle\" id=\"badge-circle8\"><span id=\"badge-pct8\">0%</span></div>\n    <h3 id=\"badge-title8\">Keep going</h3>\n    <p class=\"small\" id=\"badge-sub8\">Complete every section and the quiz to preview your certificate.</p>\n  </div>\n  <div class=\"cert-frame\">\n    <p class=\"small\">ORACLE CLOUD INFRASTRUCTURE</p>\n    <h3>Certificate of Completion</h3>\n    <p class=\"small\">This certifies that</p>\n    <div class=\"cert-name\">Your Name</div>\n    <p class=\"small\">has completed <strong>Day 8: Troubleshooting, Networking &amp; Incident Response</strong></p>\n    <p class=\"small mt-lg\">Score: <span id=\"cert-score-display8\">0/20</span> \u00b7 Date: <span id=\"cert-date-display8\"></span></p>\n  </div>\n</section>\n\n</div>\n</main>\n</div>\n<footer>OCI Troubleshooting, Networking &amp; Incident Response \u2014 Day 8 \u00b7 Interactive Learning Platform \u00b7 Single self-contained HTML file \u00b7 No external dependencies</footer>\n\n\n\n\n\n\n\n\n\n", "js": "\nconst state = { quizScore:0, quizAnswered:0, quizTotal:0, labsDone:new Set() };\ndocument.addEventListener('DOMContentLoaded', () => {\n  initParticles(); initProgressBar(); initSidebar(); initSearch(); initTheme(); initReveal();\n  initMethodology(); initIncidentLifecycle(); initRca();\n  initComputeTrouble(); initInstanceMetrics(); initInstanceLogs(); initSshTrouble(); initSerialConsole();\n  initOsiDiag(); initVpn(); initFastConnect(); initBgpRoute(); initFlowLogs(); initPathAnalyzer();\n  initLbArch(); initHealthCheck(); initSslTls(); initLoadTesting();\n  initBlockFileStorage(); initPerfAnalysis(); initObjectStorage8();\n  initConsoleSim8(); initLiveMonitoring(); initTerminal8();\n  initLabs8(); initIncidentSim(); initPostIncident(); initScenarioCenter();\n  initFlashcards8(); initQuiz8(); updateBadge8();\n});\nfunction initParticles(){\n  const c=document.getElementById('particles'); const ctx=c.getContext('2d'); let w,h,particles=[];\n  function resize(){ w=c.width=window.innerWidth; h=c.height=window.innerHeight; }\n  resize(); window.addEventListener('resize', resize);\n  const N=Math.min(60, Math.floor(window.innerWidth/24));\n  for(let i=0;i<N;i++) particles.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.6+0.4,vx:(Math.random()-0.5)*0.15,vy:(Math.random()-0.5)*0.15});\n  function tick(){ ctx.clearRect(0,0,w,h); ctx.fillStyle='rgba(199,70,52,0.5)';\n    particles.forEach(p=>{ p.x+=p.vx; p.y+=p.vy; if(p.x<0)p.x=w; if(p.x>w)p.x=0; if(p.y<0)p.y=h; if(p.y>h)p.y=0; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill(); });\n    requestAnimationFrame(tick);\n  }\n  tick();\n}\nfunction initProgressBar(){\n  const bar=document.getElementById('progress-bar'); const heroProgress=document.getElementById('hero-progress');\n  window.addEventListener('scroll', ()=>{\n    const scrollTop=window.scrollY; const docH=document.documentElement.scrollHeight-window.innerHeight;\n    const pct=docH>0?(scrollTop/docH)*100:0;\n    bar.style.width=pct+'%'; if(heroProgress) heroProgress.textContent=Math.round(pct)+'%';\n    window.__lastScrollPct8=pct; updateBadge8(); highlightActiveNav();\n  }, {passive:true});\n}\nfunction highlightActiveNav(){\n  const sections=document.querySelectorAll('section.chapter'); let current=null;\n  sections.forEach(sec=>{ const rect=sec.getBoundingClientRect(); if(rect.top<160) current=sec.id; });\n  document.querySelectorAll('#sidebar a.nav-link').forEach(a=>a.classList.toggle('active', a.getAttribute('href')==='#'+current));\n}\nfunction initSidebar(){ const sb=document.getElementById('sidebar'); document.getElementById('sidebar-toggle').addEventListener('click', ()=>sb.classList.toggle('collapsed')); }\nfunction initSearch(){\n  const input=document.getElementById('search'); const results=document.getElementById('search-results'); const index=[];\n  document.querySelectorAll('section.chapter').forEach(sec=>{\n    const title=sec.querySelector('h2')?.textContent || sec.id;\n    sec.querySelectorAll('h3').forEach(h3=>index.push({label:h3.textContent, cat:title, href:'#'+sec.id}));\n    index.push({label:title, cat:'Section', href:'#'+sec.id});\n  });\n  input.addEventListener('input', ()=>{\n    const q=input.value.trim().toLowerCase(); if(!q){results.style.display='none'; return;}\n    const matches=index.filter(i=>i.label.toLowerCase().includes(q)).slice(0,8);\n    results.innerHTML=matches.map(m=>`<a href=\"${m.href}\"><span class=\"sr-cat\">${m.cat}</span>${m.label}</a>`).join('') || '<a style=\"cursor:default;\">No results</a>';\n    results.style.display='block';\n  });\n  document.addEventListener('click', e=>{ if(!document.getElementById('search-wrap').contains(e.target)) results.style.display='none'; });\n  results.addEventListener('click', ()=>setTimeout(()=>{results.style.display='none'; input.value='';},10));\n}\nfunction initTheme(){\n  const btn=document.getElementById('theme-toggle');\n  btn.addEventListener('click', ()=>{ const html=document.documentElement; const isDark=html.getAttribute('data-theme')!=='light'; html.setAttribute('data-theme', isDark?'light':'dark'); btn.textContent=isDark?'\u2600\ufe0f':'\ud83c\udf19'; });\n}\nfunction initReveal(){\n  const els=document.querySelectorAll('.reveal');\n  const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in');}), {threshold:0.08});\n  els.forEach(el=>io.observe(el));\n}\n\n;\n\n/* ---------- troubleshooting methodology decision ---------- */\nfunction initMethodology(){\n  const btns = document.querySelectorAll('[data-mstep]'); if(!btns.length) return;\n  const outcome = document.getElementById('mstep-1-outcome');\n  btns.forEach(b=>{\n    b.addEventListener('click', ()=>{\n      if(b.dataset.choice==='identify'){ outcome.className='fd-outcome good'; outcome.textContent='\u2713 Correct \u2014 check backend health first. Restarting servers blindly can mask the real cause and even cause a second outage.'; }\n      else { outcome.className='fd-outcome bad'; outcome.textContent='\u2717 Restarting without diagnosis risks losing evidence (logs, connection state) needed to find the actual root cause \u2014 and the problem may just recur.'; }\n    });\n  });\n}\n\n/* ---------- incident lifecycle timeline ---------- */\nfunction initIncidentLifecycle(){\n  const wrap = document.getElementById('incident-timeline'); if(!wrap) return;\n  const steps = ['Alert Fired','Investigation','Diagnosis','Mitigation','Recovery','Postmortem','Lessons Learned'];\n  wrap.innerHTML = steps.map(s=>`<div class=\"inc-step\">${s}</div>`).join('');\n  document.getElementById('incident-play').addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.inc-step'); els.forEach(e=>e.classList.remove('lit'));\n    steps.forEach((s,i)=> setTimeout(()=> els[i].classList.add('lit'), i*500));\n  });\n}\n\n/* ---------- 5 whys builder ---------- */\nfunction initRca(){\n  const wrap = document.getElementById('why-builder'); if(!wrap) return;\n  const placeholders = [\n    'Why did checkout return 502s? e.g. \"The backend servers stopped responding\"',\n    'Why did the backend servers stop responding? e.g. \"They ran out of memory\"',\n    'Why did they run out of memory? e.g. \"A memory leak in the payment module\"',\n  ];\n  let count = 1;\n  function render(){\n    wrap.innerHTML = '';\n    for(let i=0;i<count;i++){\n      const row = document.createElement('div');\n      row.className='why-row';\n      row.innerHTML = `<div class=\"why-num\">${i+1}</div><input class=\"mini-input\" placeholder=\"${placeholders[i] || 'Why did that happen?'}\">`;\n      wrap.appendChild(row);\n    }\n  }\n  document.getElementById('why-add').addEventListener('click', ()=>{ if(count<5){ count++; render(); } });\n  render();\n}\n\n;\n\n/* ---------- compute troubleshooting ---------- */\nfunction initComputeTrouble(){\n  const btn = document.getElementById('ct-launch'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const log = document.getElementById('ct-log');\n    const lines = ['Validating launch request...','Reserving shape VM.Standard.E4.Flex...','Creating boot volume...','Instance state: PROVISIONING','Instance state: FAILED','\u2717 Launch failed.'];\n    log.textContent='';\n    lines.forEach((l,i)=> setTimeout(()=>{ log.textContent += l+'\\n'; log.scrollTop=log.scrollHeight;\n      if(i===lines.length-1) document.getElementById('ct-diag-btns').style.display='flex';\n    }, i*400));\n  });\n  const causes = {\n    capacity: 'Root cause: Out of Host Capacity for that shape/AD combination. Fix: try a different AD, a different shape family, or use a Capacity Reservation.',\n    shape: 'Root cause: the selected shape is not offered in this region/AD. Fix: check shape availability per region before launch, or pick a supported alternative.',\n    image: 'Root cause: the custom image failed validation (corrupted or incompatible). Fix: re-export/re-import the image, or use a known-good Oracle-provided image.',\n    cloudinit: 'Root cause: a cloud-init syntax error halted provisioning validation. Fix: validate your cloud-config YAML before launch.',\n    bootvol: 'Root cause: the boot volume failed to provision (backend capacity/service issue). Fix: retry the launch; open a support ticket if it recurs.'\n  };\n  document.querySelectorAll('[data-ctdiag]').forEach(b=>{\n    b.addEventListener('click', ()=>{\n      document.querySelectorAll('[data-ctdiag]').forEach(x=>x.classList.remove('active')); b.classList.add('active');\n      document.getElementById('ct-diag-result').innerHTML = '\ud83d\udd0e ' + causes[b.dataset.ctdiag];\n    });\n  });\n}\n\n/* ---------- instance metrics dashboard ---------- */\nfunction initInstanceMetrics(){\n  const wrap = document.getElementById('metric-grid'); if(!wrap) return;\n  const metrics = [\n    {label:'CPU Utilization', val:'92%', alert:true},\n    {label:'Memory Usage', val:'68%', alert:false},\n    {label:'Disk I/O Latency', val:'4ms', alert:false},\n    {label:'Network Throughput', val:'340 Mbps', alert:false},\n  ];\n  wrap.innerHTML = metrics.map((m,i)=>`\n    <div class=\"metric-card ${m.alert?'alert':''}\"><div class=\"m-label\">${m.label}</div><div class=\"m-val\">${m.val}</div><canvas id=\"metric-canvas-${i}\" width=\"200\" height=\"50\"></canvas></div>`).join('');\n  metrics.forEach((m,i)=>{\n    const canvas = document.getElementById('metric-canvas-'+i); const ctx = canvas.getContext('2d');\n    const w = canvas.width=canvas.clientWidth||200, h=canvas.height=50;\n    const pts = Array.from({length:20}, ()=> Math.random()*(m.alert?20:40) + (m.alert?70:20));\n    ctx.beginPath();\n    pts.forEach((p,j)=>{ const x=(j/(pts.length-1))*w; const y=h-(p/100)*h; if(j===0) ctx.moveTo(x,y); else ctx.lineTo(x,y); });\n    ctx.strokeStyle = m.alert ? '#ff5a3c' : '#4f8cff'; ctx.lineWidth=2; ctx.stroke();\n  });\n}\n\n/* ---------- instance log explorer ---------- */\nfunction initInstanceLogs(){\n  const tabs = document.querySelectorAll('#log-tabs .chip-btn'); if(!tabs.length) return;\n  const viewer = document.getElementById('log-viewer'); const search = document.getElementById('log-search');\n  const logs = {\n    boot: `[    0.000000] Booting Linux on physical CPU 0x0\\n[    2.114000] systemd[1]: Started Journal Service\\n[    4.882000] systemd[1]: Reached target Network\\n[    5.201000] systemd[1]: Started SSH Daemon\\n[    5.900000] cloud-init: starting stage: init-local`,\n    console: `[opc@web-vm-01 ~]$ systemctl status nginx\\n\u25cf nginx.service - active (running)\\n[opc@web-vm-01 ~]$ df -h\\nFilesystem  Size  Used  Avail\\n/dev/sda1    50G   12G   38G`,\n    cloudinit: `Cloud-init v. 23.4 running 'init-local'\\nCloud-init v. 23.4 running 'modules:config'\\nCiInstallError: package 'ngnix' not found\\ncloud-init: error running module packages\\nCloud-init v. 23.4 finished with 1 error`,\n    kernel: `[   12.442] EXT4-fs (sda1): mounted filesystem\\n[   14.881] eth0: link up, 10Gbps, full-duplex\\n[   88.223] TCP: out of memory -- consider tuning tcp_mem\\n[   88.224] nginx invoked oom-killer`\n  };\n  function render(tab, q){\n    let text = logs[tab];\n    viewer.innerHTML = text.split('\\n').map(line=>{\n      if(q && line.toLowerCase().includes(q.toLowerCase())){\n        const re = new RegExp('('+q.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&')+')','ig');\n        return line.replace(re, '<mark>$1</mark>');\n      }\n      return line;\n    }).join('\\n');\n  }\n  let currentTab = 'boot';\n  tabs.forEach(t=> t.addEventListener('click', ()=>{ tabs.forEach(x=>x.classList.remove('active')); t.classList.add('active'); currentTab = t.dataset.logtab; render(currentTab, search.value); }));\n  search.addEventListener('input', ()=> render(currentTab, search.value));\n  render('boot','');\n}\n\n/* ---------- SSH troubleshooting ---------- */\nfunction initSshTrouble(){\n  const cards = document.querySelectorAll('.ssh-cause-card'); if(!cards.length) return;\n  const panel = document.getElementById('ssh-detail-panel');\n  const info = {\n    wrongkey: {sym:'Permission denied (publickey).', fix:'The private key you\\'re using doesn\\'t match the public key injected at launch. Verify you\\'re using the correct key pair for this instance.'},\n    wronguser: {sym:'Permission denied (publickey), even with the right key.', fix:'Default usernames differ by image: opc (Oracle Linux), ubuntu (Ubuntu), ec2-user pattern doesn\\'t apply here \u2014 check the image documentation.'},\n    port22: {sym:'ssh: connect to host ... port 22: Connection timed out', fix:'A network firewall (on-prem, corporate proxy, or the instance\\'s own firewalld) is blocking outbound/inbound port 22.'},\n    nsg: {sym:'Connection timed out', fix:'The VNIC\\'s Network Security Group has no ingress rule allowing TCP/22 from your IP.'},\n    seclist: {sym:'Connection timed out', fix:'The subnet\\'s Security List has no ingress rule allowing TCP/22 \u2014 check this even if the NSG looks correct, both must allow it.'},\n    route: {sym:'Connection timed out, but Security List/NSG look correct', fix:'The subnet\\'s route table is missing a route to the Internet Gateway (for a public subnet) \u2014 the response has nowhere to go.'},\n    nopublicip: {sym:'Could not resolve hostname / no route to host', fix:'The instance never got a public IP \u2014 it\\'s either in a private subnet or the public IP assignment was skipped at launch.'},\n    cloudinit: {sym:'SSH port is open, but authentication always fails', fix:'cloud-init failed before it could inject your SSH key into ~/.ssh/authorized_keys \u2014 check /var/log/cloud-init-output.log via Serial Console.'}\n  };\n  cards.forEach(c=>{\n    c.addEventListener('click', ()=>{\n      cards.forEach(x=>x.classList.remove('active')); c.classList.add('active');\n      const i = info[c.dataset.ssh];\n      panel.innerHTML = `<p class=\"mono\" style=\"color:var(--red-bright);\">${i.sym}</p><p class=\"small mt-lg\" style=\"color:var(--green);\">\u2713 ${i.fix}</p>`;\n    });\n  });\n}\n\n/* ---------- serial console & run commands ---------- */\nfunction initSerialConsole(){\n  const btn = document.getElementById('serial-connect'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const log = document.getElementById('serial-log'); log.style.display='block';\n    log.textContent = 'Connecting to serial console...\\n\\n[  OK  ] Started Network Manager\\n[FAILED] Failed to start Network Configuration\\nWelcome to Oracle Linux Server 9\\nlogin: _';\n    document.getElementById('serial-fix-row').style.display='block';\n  });\n  document.getElementById('serial-fix').addEventListener('click', ()=>{\n    document.getElementById('serial-fix-result').innerHTML = '\u2713 Network configuration corrected and instance rebooted \u2014 SSH access restored. This is exactly the scenario Serial Console exists for: recovering an instance with zero working network path.';\n  });\n  const select = document.getElementById('runcmd-select'); const execBtn = document.getElementById('runcmd-execute');\n  const responses = {\n    uptime: ' 14:32:01 up 12 days,  3:41,  1 user,  load average: 8.42, 7.91, 6.88',\n    diskspace: 'Filesystem      Size  Used Avail Use% Mounted on\\n/dev/sda1        50G   48G  1.2G  98% /',\n    services: '\u25cf nginx.service - active (running) since Mon 2026-07-20\\n   Main PID: 1042 (nginx)'\n  };\n  execBtn.addEventListener('click', ()=>{\n    document.getElementById('runcmd-out').textContent = `$ Run Command executing (no SSH)...\\n${responses[select.value]}`;\n  });\n}\n\n;\n\n/* ---------- OSI layer diagnosis ---------- */\nfunction initOsiDiag(){\n  const btn = document.getElementById('osidiag-run'); if(!btn) return;\n  const wrap = document.getElementById('osidiag-steps');\n  const steps = ['L1 Physical: link up','L2 Data Link: ARP resolves','L3 Network: route table has a path','L4 Transport: TCP handshake fails here','L7 Application: never reached'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  btn.addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    const result = document.getElementById('osidiag-result');\n    steps.forEach((s,i)=> setTimeout(()=>{\n      els[i].classList.add('lit');\n      if(i===3){ result.innerHTML = '\ud83d\udd0e Found it at Layer 4 \u2014 the TCP handshake never completes. This points to a Security List/NSG blocking the port, not a routing or physical issue.'; result.style.color='var(--amber)'; }\n      if(i===steps.length-1) setTimeout(()=>{ result.innerHTML += '<br>\u2713 Fix: check the destination port\\'s ingress rule in the Security List/NSG.'; result.style.color='var(--green)'; }, 400);\n    }, i*450));\n  });\n}\n\n/* ---------- VPN topology & failure lab ---------- */\nfunction initVpn(){\n  const btns = document.querySelectorAll('[data-vpnfail]'); if(!btns.length) return;\n  const t1 = document.getElementById('vpn-tunnel1'); const t2 = document.getElementById('vpn-tunnel2');\n  const cpe = document.getElementById('vpn-cpe'); const drg = document.getElementById('vpn-drg');\n  const info = {\n    tunneldown: 'Tunnel state: DOWN. Fix: check the CPE\\'s public IP hasn\\'t changed, and that the CPE device is actually up and configured.',\n    sharedsecret: 'IKE Phase 1 fails to establish. Fix: the pre-shared key on the CPE must exactly match the one configured on the OCI IPSec connection.',\n    routemissing: 'Tunnel is UP but no traffic flows. Fix: add a route rule in the VCN\\'s route table pointing the on-prem CIDR to the DRG.',\n    ikefail: 'IKE negotiation failure. Fix: verify IKE version (v1/v2), encryption/DH group parameters match on both sides.',\n    ipsecfail: 'Phase 2 (IPSec) fails after Phase 1 succeeds. Fix: verify the Phase 2 proposal (encryption domain / CIDRs) matches on both ends.'\n  };\n  btns.forEach(b=>{\n    b.addEventListener('click', ()=>{\n      btns.forEach(x=>x.classList.remove('active')); b.classList.add('active');\n      t1.classList.remove('up'); t1.classList.add('down'); t2.classList.remove('up');\n      document.getElementById('vpnfail-result').innerHTML = '\ud83d\udd0e ' + info[b.dataset.vpnfail];\n    });\n  });\n}\n\n/* ---------- FastConnect failure lab ---------- */\nfunction initFastConnect(){\n  const btns = document.querySelectorAll('[data-fcfail]'); if(!btns.length) return;\n  const info = {\n    provisioning: 'The provider hasn\\'t completed activating the cross-connect on their side yet. Fix: confirm activation status with the FastConnect provider.',\n    routeissue: 'Cross-connect is up, but no route exists. Fix: verify route table entries pointing the on-prem CIDR to the DRG via the virtual circuit.',\n    bgpfail: 'BGP session stuck in Idle/Active. Fix: verify BGP ASN and peering IP configuration match on both ends.',\n    bandwidth: 'Circuit is up but throughput is capped. Fix: check the provisioned bandwidth tier matches actual demand \u2014 upgrade the virtual circuit if undersized.'\n  };\n  btns.forEach(b=>{\n    b.addEventListener('click', ()=>{\n      btns.forEach(x=>x.classList.remove('active')); b.classList.add('active');\n      document.getElementById('fcfail-result').innerHTML = '\ud83d\udd0e ' + info[b.dataset.fcfail];\n    });\n  });\n}\n\n/* ---------- BGP & route table analyzer ---------- */\nfunction initBgpRoute(){\n  const wrap = document.getElementById('bgp-peers'); if(!wrap) return;\n  let peers = [{name:'on-prem-router-1', asn:65001, state:'established'}, {name:'on-prem-router-2', asn:65002, state:'established'}];\n  function render(){\n    wrap.innerHTML = peers.map(p=>`<div class=\"bgp-peer\"><span>${p.name} (AS${p.asn})</span><span class=\"bgp-state ${p.state}\">${p.state}</span></div>`).join('');\n  }\n  document.getElementById('bgp-flap').addEventListener('click', ()=>{\n    peers[0].state='idle'; render();\n  });\n  document.getElementById('bgp-reset').addEventListener('click', ()=>{\n    peers.forEach(p=> p.state='established'); render();\n  });\n  render();\n\n  function prefixLen(cidr){ return parseInt(cidr.split('/')[1]); }\n  function ipInRange(ip, cidr){\n    const [netIp,pfx] = cidr.split('/'); const p = parseInt(pfx);\n    const toInt = s=> s.split('.').reduce((a,o)=>(a<<8)+parseInt(o),0)>>>0;\n    const mask = p===0?0:(0xFFFFFFFF<<(32-p))>>>0;\n    return (toInt(ip)&mask) === (toInt(netIp)&mask);\n  }\n  const rules = [['10.0.0.0/16','local'],['172.16.0.0/16','DRG (on-prem)'],['0.0.0.0/0','Internet Gateway']];\n  document.getElementById('route8-check').addEventListener('click', ()=>{\n    const ip = document.getElementById('route8-test').value.trim();\n    const result = document.getElementById('route8-result');\n    if(!ip){ result.textContent='Enter a test IP.'; return; }\n    const matches = rules.filter(([d])=> ipInRange(ip,d)).sort((a,b)=> prefixLen(b[0])-prefixLen(a[0]));\n    if(matches.length===0){ result.textContent = `No matching route for ${ip}.`; result.style.color='var(--red-bright)'; }\n    else { result.innerHTML = `\u2713 Longest-prefix-match: <span class=\"mono\" style=\"color:var(--blue);\">${matches[0][0]} \u2192 ${matches[0][1]}</span>`; result.style.color='var(--green)'; }\n  });\n}\n\n/* ---------- flow logs ---------- */\nfunction initFlowLogs(){\n  const wrap = document.getElementById('flowlog-list'); if(!wrap) return;\n  const logs = [\n    {src:'203.0.113.5:51422', dst:'10.0.1.10:443', action:'accepted'},\n    {src:'198.51.100.9:33221', dst:'10.0.1.10:22', action:'rejected'},\n    {src:'10.0.1.15:40912', dst:'10.0.2.20:5432', action:'accepted'},\n    {src:'192.0.2.44:60123', dst:'10.0.1.10:3389', action:'rejected'},\n    {src:'10.0.1.10:443', dst:'203.0.113.5:51422', action:'accepted'},\n  ];\n  function render(filter){\n    const filtered = logs.filter(l=> filter==='all' || l.action===filter);\n    wrap.innerHTML = filtered.map(l=>`<div class=\"flowlog-row ${l.action}\">${l.src} \u2192 ${l.dst} : ${l.action.toUpperCase()}</div>`).join('') || '<p class=\"small\">No matching entries.</p>';\n  }\n  document.querySelectorAll('#flowlog-filters .chip-btn').forEach(btn=>{\n    btn.addEventListener('click', ()=>{ document.querySelectorAll('#flowlog-filters .chip-btn').forEach(b=>b.classList.remove('active')); btn.classList.add('active'); render(btn.dataset.flt); });\n  });\n  render('all');\n}\n\n/* ---------- path analyzer & asymmetric routing ---------- */\nfunction initPathAnalyzer(){\n  const btn = document.getElementById('patha-run'); if(!btn) return;\n  const wrap = document.getElementById('patha-hops');\n  const hops = [\n    ['Client', 'ok'], ['Load Balancer (listener)', 'ok'], ['Security List (subnet)', 'ok'], ['NSG (VNIC)', 'blocked'], ['app-vm-01', 'unreached']\n  ];\n  btn.addEventListener('click', ()=>{\n    wrap.innerHTML='';\n    hops.forEach(([name,status],i)=> setTimeout(()=>{\n      const div = document.createElement('div');\n      div.className = 'path-hop ' + (status==='blocked'?'blocked':'ok');\n      div.innerHTML = `<span class=\"hop-status\"></span><span>${name} \u2014 ${status==='blocked'?'BLOCKED':status==='unreached'?'never reached':'passed'}</span>`;\n      wrap.appendChild(div);\n    }, i*400));\n  });\n\n  document.getElementById('asymroute-identify').addEventListener('click', ()=>{\n    document.getElementById('asymroute-result').innerHTML = '\u2713 This is classic asymmetric routing \u2014 stateful firewalls only see one direction of the conversation and drop the \"unrecognized\" return traffic. Fix: ensure both directions of a flow traverse the same firewall/path, or use policy-based routing to force symmetry.';\n  });\n}\n\n;\n\n/* ---------- LB architecture dashboard ---------- */\nfunction initLbArch(){\n  const wrap = document.getElementById('lb-dashboard'); if(!wrap) return;\n  wrap.innerHTML = `\n    <div class=\"lb-backend-row\"><span><span class=\"lb-health-dot healthy\"></span>backend-1 (10.0.1.11:8080)</span><span class=\"small\">Listener: HTTPS:443</span></div>\n    <div class=\"lb-backend-row\"><span><span class=\"lb-health-dot healthy\"></span>backend-2 (10.0.1.12:8080)</span><span class=\"small\">Backend Set: web-backend-set</span></div>\n    <div class=\"lb-backend-row\"><span><span class=\"lb-health-dot unhealthy\"></span>backend-3 (10.0.1.13:8080)</span><span class=\"small\">Health check: FAILING</span></div>`;\n}\n\n/* ---------- health check simulator ---------- */\nfunction initHealthCheck(){\n  const interval = document.getElementById('hc-interval'); if(!interval) return;\n  interval.addEventListener('input', ()=> document.getElementById('hc-interval-val').textContent = interval.value+'s');\n  const list = document.getElementById('lb-backends-list');\n  document.getElementById('hc-apply').addEventListener('click', ()=>{\n    const path = document.getElementById('hc-path').value;\n    const port = document.getElementById('hc-port').value;\n    const healthy = (path==='/health' && port==='8080');\n    list.innerHTML = ['backend-1','backend-2','backend-3'].map(b=>`<div class=\"lb-backend-row\"><span><span class=\"lb-health-dot ${healthy?'healthy':'unhealthy'}\"></span>${b}</span><span class=\"small\">${healthy?'200 OK':'Connection refused on '+port+path}</span></div>`).join('');\n  });\n  document.getElementById('hc-apply').click();\n\n  const btns = document.querySelectorAll('#unhealthy-btns .chip-btn');\n  const info = {\n    firewall: 'The NSG/Security List on the backend subnet doesn\\'t allow the health check port from the LB\\'s subnet. Fix: add an ingress rule for the health check port from the LB subnet CIDR.',\n    app: 'The application is running but doesn\\'t implement a /health endpoint, or it\\'s returning a non-2xx status. Fix: implement a lightweight health endpoint that reflects real app readiness.',\n    wrongport: 'The health check is configured for port 80, but the app listens on 8080. Fix: align the health check port with the actual application port.',\n    dns: 'The backend was registered by hostname, and DNS resolution inside the VCN is failing. Fix: verify VCN DNS resolution is enabled, or register backends by IP instead.'\n  };\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); document.getElementById('unhealthy-result').innerHTML = '\ud83d\udd0e ' + info[b.dataset.uh]; }));\n}\n\n/* ---------- SSL/TLS & HTTP errors ---------- */\nfunction initSslTls(){\n  const btns = document.querySelectorAll('#ssl-case-btns .chip-btn'); if(!btns.length) return;\n  const info = {\n    mismatch: 'The certificate installed on the LB doesn\\'t match the private key, or is for a different domain entirely. Fix: re-upload the matching cert/key pair.',\n    expired: 'The certificate\\'s validity window has passed. Fix: renew and re-upload before expiry; automate renewal going forward.',\n    wrongcn: 'The certificate\\'s CN/SAN list doesn\\'t include the hostname being requested. Fix: reissue the cert including all required hostnames as SANs.'\n  };\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); document.getElementById('ssl-case-result').innerHTML = '\ud83d\udd0e ' + info[b.dataset.sslcase]; }));\n\n  const cards = document.querySelectorAll('#http-error-grid .http-error-card');\n  const detail = document.getElementById('http-error-detail');\n  const errInfo = {\n    400: 'Bad Request \u2014 malformed request syntax or invalid parameters from the client.',\n    401: 'Unauthorized \u2014 authentication is missing or invalid.',\n    403: 'Forbidden \u2014 authenticated, but not permitted to access this resource.',\n    404: 'Not Found \u2014 the requested resource doesn\\'t exist at this path.',\n    500: 'Internal Server Error \u2014 the backend application crashed or threw an unhandled exception.',\n    502: 'Bad Gateway \u2014 the LB got an invalid response from the backend (often the backend crashed mid-request).',\n    503: 'Service Unavailable \u2014 no healthy backends are available in the backend set.',\n    504: 'Gateway Timeout \u2014 the backend took too long to respond within the LB\\'s timeout window.'\n  };\n  cards.forEach(c=> c.addEventListener('click', ()=>{ detail.textContent = errInfo[c.dataset.code]; }));\n}\n\n/* ---------- load testing ---------- */\nfunction initLoadTesting(){\n  const btn = document.getElementById('loadtest-run'); if(!btn) return;\n  const wrap = document.getElementById('loadtest-metrics');\n  function render(spiked){\n    const metrics = [\n      {label:'Requests/sec', val: spiked?'8,420':'840'},\n      {label:'Avg Response Time', val: spiked?'1.8s':'110ms'},\n      {label:'5xx Error Rate', val: spiked?'12%':'0.1%'},\n      {label:'Active Backends', val: spiked?'2 of 3 (1 overloaded)':'3 of 3'},\n    ];\n    wrap.innerHTML = metrics.map(m=>`<div class=\"metric-card ${spiked?'alert':''}\"><div class=\"m-label\">${m.label}</div><div class=\"m-val\">${m.val}</div></div>`).join('');\n  }\n  render(false);\n  btn.addEventListener('click', ()=> render(true));\n}\n\n;\n\n/* ---------- block & file storage troubleshooting ---------- */\nfunction initBlockFileStorage(){\n  const btns = document.querySelectorAll('#bv-issue-btns .chip-btn'); if(!btns.length) return;\n  const info = {\n    attach: 'Volume and instance are in different Availability Domains \u2014 block volumes can only attach to instances in the same AD. Fix: verify AD placement, or use a multipath/iSCSI volume that supports cross-AD if applicable.',\n    detach: 'The volume is still mounted at the OS level. Fix: unmount the filesystem inside the instance first, then detach via the Console/CLI.',\n    perf: 'The volume\\'s performance tier (VPU/GB) is too low for the workload\\'s IOPS demand. Fix: increase the volume performance tier or move to a higher-performance shape.',\n    backup: 'The backup policy references a compartment or IAM principal that no longer has permission. Fix: verify the policy grants \"manage volume-backups\" in the right compartment.',\n    restore: 'Restoring to a smaller volume size than the original backup. Fix: the restored volume must be at least as large as the source backup.'\n  };\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); document.getElementById('bv-issue-result').innerHTML = '\ud83d\udd0e ' + info[b.dataset.bvissue]; }));\n\n  const checklist = document.getElementById('nfs-diag-checklist'); if(!checklist) return;\n  const checks = ['Mount target NSG allows TCP/UDP 2048-2050, 111 from client subnet','Export path exists and matches the mount command','Client subnet is in the same VCN (or peered) as the mount target','DNS/IP of the mount target is reachable'];\n  checklist.innerHTML = checks.map(c=>`<div class=\"diag-check-row\"><span class=\"dc-status\">\u23f3</span><span>${c}</span></div>`).join('');\n  document.getElementById('nfs-diag-run').addEventListener('click', ()=>{\n    const rows = checklist.querySelectorAll('.diag-check-row');\n    rows.forEach((r,i)=> setTimeout(()=>{\n      const bad = i===0;\n      r.querySelector('.dc-status').textContent = bad ? '\u2717' : '\u2713';\n      r.style.color = bad ? 'var(--red-bright)' : 'var(--green)';\n    }, i*400));\n  });\n}\n\n/* ---------- performance analysis (iostat) ---------- */\nfunction initPerfAnalysis(){\n  const out = document.getElementById('iostat-out'); if(!out) return;\n  out.textContent = `Device            r/s     w/s   rkB/s   wkB/s  await  %util\nsda              2.10   840.5    84.2  67240.1  142.30  98.7\nsdb              0.50     5.2    12.0    420.5    2.10   4.2`;\n  document.getElementById('iostat-analysis').innerHTML = '\ud83d\udd0e sda shows 98.7% utilization and 142ms average wait time \u2014 this disk is saturated. Combined with a very high write rate (840 w/s), this points to a write-heavy workload exceeding the volume\\'s provisioned IOPS. Fix: increase the volume\\'s performance tier or move hot data to a higher-IOPS volume.';\n}\n\n/* ---------- object storage troubleshooting ---------- */\nfunction initObjectStorage8(){\n  const btns = document.querySelectorAll('#os-issue-btns .chip-btn'); if(!btns.length) return;\n  const info = {\n    permission: 'The calling principal lacks \"use object-family\" or \"manage objects\" on this bucket\\'s compartment. Fix: update the IAM policy to grant the correct verb.',\n    lifecycle: 'A lifecycle policy auto-deleted or archived objects older than the configured threshold. Fix: review the lifecycle rule\\'s age threshold and adjust or restore from Archive if needed.',\n    versioning: 'The app is requesting the object without specifying a version, and an older version was somehow made \"current\" (e.g. after a delete-marker rollback). Fix: explicitly request the intended version ID.',\n    access: 'The application\\'s instance principal isn\\'t covered by the dynamic group\\'s matching rule. Fix: update the dynamic group rule to include this instance/compartment.'\n  };\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); document.getElementById('os-issue-result').innerHTML = '\ud83d\udd0e ' + info[b.dataset.osissue]; }));\n}\n\n;\n\n/* ---------- console simulator 8 ---------- */\nfunction initConsoleSim8(){\n  const nav = document.querySelectorAll('.console-nav div[data-panel8]'); if(!nav.length) return;\n  nav.forEach(item=>{\n    item.addEventListener('click', ()=>{\n      nav.forEach(n=>n.classList.remove('active')); item.classList.add('active');\n      document.querySelectorAll('.console-panel8').forEach(p=>p.style.display='none');\n      document.getElementById('panel8-'+item.dataset.panel8).style.display='';\n    });\n  });\n  const restartBtn = document.getElementById('c8-restart');\n  if(restartBtn) restartBtn.addEventListener('click', function(){\n    const row = this.closest('tr');\n    row.querySelector('.status-pill').className='status-pill active'; row.querySelector('.status-pill').textContent='Running';\n    this.disabled = true; this.textContent='Restarted';\n  });\n}\n\n/* ---------- live monitoring dashboard ---------- */\nfunction initLiveMonitoring(){\n  const wrap = document.getElementById('livemon-grid'); if(!wrap) return;\n  const metrics = [\n    ['CPU', '76%', false], ['Memory', '54%', false], ['Network', '210 Mbps', false], ['Disk', '38%', false],\n    ['Health Checks', '2/3 healthy', true], ['VPN Tunnels', '1/2 up', true], ['Latency', '340ms', true], ['Error Rate', '4.2%', true],\n  ];\n  wrap.innerHTML = metrics.map(([label,val,alert])=> `<div class=\"metric-card ${alert?'alert':''}\"><div class=\"m-label\">${label}</div><div class=\"m-val\">${val}</div></div>`).join('');\n}\n\n/* ---------- CLI terminal 8 ---------- */\nfunction initTerminal8(){\n  const out = document.getElementById('term-out8'); const input = document.getElementById('term-input8'); if(!input) return;\n  const responses = {\n    'help': `Available commands:\n  oci compute instance list\n  oci compute instance action\n  oci compute console-history capture\n  oci network vcn list\n  oci network ipsec list\n  oci network fast-connect-provider-service list\n  oci lb backend-health get\n  oci bv volume list\n  oci fs export list\n  oci logging log list\n  clear`,\n    'oci compute instance list': `{ \"data\": [{\"display-name\": \"web-vm-01\", \"lifecycle-state\": \"STOPPED\"}] }`,\n    'oci compute instance action': `{ \"data\": {\"display-name\": \"web-vm-01\", \"lifecycle-state\": \"STARTING\"} }`,\n    'oci compute console-history capture': `{ \"data\": {\"id\": \"ocid1.consolehistory.oc1..aaa\", \"lifecycle-state\": \"SUCCEEDED\"} }`,\n    'oci network vcn list': `{ \"data\": [{\"display-name\": \"prod-vcn\", \"lifecycle-state\": \"AVAILABLE\"}] }`,\n    'oci network ipsec list': `{ \"data\": [{\"display-name\": \"onprem-ipsec\", \"lifecycle-state\": \"AVAILABLE\"}] }`,\n    'oci network fast-connect-provider-service list': `{ \"data\": [{\"provider-name\": \"Equinix\", \"type\": \"LAYER2\"}] }`,\n    'oci lb backend-health get': `{ \"data\": {\"status\": \"CRITICAL\", \"total-backend-count\": 3, \"unknown-state-backend-names\": [], \"critical-state-backend-names\": [\"backend-3\"]} }`,\n    'oci bv volume list': `{ \"data\": [{\"display-name\": \"data-vol-01\", \"lifecycle-state\": \"AVAILABLE\"}] }`,\n    'oci fs export list': `{ \"data\": [{\"export-set-id\": \"ocid1.exportset.oc1..aaa\", \"path\": \"/shared-data\"}] }`,\n    'oci logging log list': `{ \"data\": [{\"display-name\": \"vcn-flow-logs\", \"log-type\": \"SERVICE\"}] }`\n  };\n  function esc(s){ return s.replace(/[&<>]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }\n  function print(cmd, text, isErr){\n    const line = document.createElement('div');\n    line.innerHTML = `<div class=\"cmdline\">${esc(cmd)}</div><div style=\"color:${isErr?'#ff8a7a':'#c9f7d8'}; margin:4px 0 12px; white-space:pre-wrap;\">${esc(text)}</div>`;\n    out.appendChild(line); out.scrollTop = out.scrollHeight;\n  }\n  print('help', 'Welcome to the OCI CLI simulator. Type \"help\" for the supported command list.');\n  input.addEventListener('keydown', e=>{\n    if(e.key!=='Enter') return;\n    const cmd = input.value.trim(); input.value=''; if(!cmd) return;\n    if(cmd==='clear'){ out.innerHTML=''; return; }\n    if(responses[cmd]){ print(cmd, responses[cmd]); return; }\n    print(cmd, 'Command not recognized in this simulator. Type \"help\" for the supported list.', true);\n  });\n}\n\n;\n\n/* ---------- hands-on labs checklist ---------- */\nfunction initLabs8(){\n  const wrap = document.getElementById('labs8-list'); if(!wrap) return;\n  const labs = [\n    ['Fix SSH Access','Work through the SSH Troubleshooting causes.'],\n    ['Repair Cloud-init Failure','Diagnose the cloud-init case in Compute Troubleshooting.'],\n    ['Recover Boot Failure','Use Serial Console to repair a broken instance.'],\n    ['Repair VPN Tunnel','Diagnose a case in the VPN Failure Lab.'],\n    ['Fix FastConnect Routing','Diagnose a case in the FastConnect Failure Lab.'],\n    ['Diagnose Flow Logs','Filter rejected traffic in the Flow Logs explorer.'],\n    ['Repair Load Balancer','Diagnose an unhealthy backend.'],\n    ['Replace SSL Certificate','Work through an SSL/TLS case.'],\n    ['Attach Block Volume','Diagnose a Block Volume attach failure.'],\n    ['Fix NFS Mount','Run the NFS mount diagnostics.'],\n    ['Storage Performance Investigation','Review the iostat performance analysis.'],\n  ];\n  wrap.innerHTML = labs.map(([t,d],i)=>`<div class=\"lab-item\" data-i=\"${i}\"><div class=\"lab-check\">\u2713</div><div><div class=\"lab-title\">Lab ${i+1}: ${t}</div><div class=\"lab-desc\">${d}</div></div></div>`).join('');\n  function updateProgress(){ document.getElementById('labs8-progress').textContent = `${wrap.querySelectorAll('.lab-item.done').length} / ${labs.length} labs complete`; }\n  wrap.querySelectorAll('.lab-item').forEach(item=> item.addEventListener('click', ()=>{ item.classList.toggle('done'); updateProgress(); updateBadge8(); }));\n  updateProgress();\n}\n\n/* ---------- multi-layer incident simulator ---------- */\nfunction initIncidentSim(){\n  const tabs = document.querySelectorAll('#incident-layer-tabs .chip-btn'); if(!tabs.length) return;\n  const findings = document.getElementById('incident-findings');\n  const submitBtn = document.getElementById('incident-submit');\n  const layerInfo = {\n    compute: 'Instances are RUNNING, CPU/memory normal. Nothing wrong here \u2014 but this took time to rule out, which is expected.',\n    network: 'VCN, route tables, and gateways all healthy. Not the cause.',\n    security: 'Security Lists and NSGs unchanged recently. Not the cause.',\n    storage: 'Block volumes attached and healthy, no I/O errors. Not the cause.',\n    lb: 'Load balancer backend set shows all 3 backends healthy \u2014 traffic IS reaching them.',\n    dns: 'DNS resolving correctly, no recent changes. Not the cause.',\n    application: '\ud83d\udd0e Found it: the checkout service\\'s payment-processing pod has been crash-looping since a deploy 20 minutes ago \u2014 an unhandled null reference in the new discount-code feature.'\n  };\n  const investigated = new Set();\n  tabs.forEach(t=>{\n    t.addEventListener('click', ()=>{\n      investigated.add(t.dataset.layer); t.classList.add('investigated');\n      findings.textContent = layerInfo[t.dataset.layer];\n      if(t.dataset.layer==='application') submitBtn.style.display='inline-flex';\n    });\n  });\n  submitBtn.addEventListener('click', ()=>{\n    findings.innerHTML += '<br><br>\u2713 Root cause correctly identified: an application deploy bug, not infrastructure. This incident is now ready for the Post-Incident Review.';\n    state.labsDone.add('incident-sim');\n  });\n}\n\n/* ---------- post-incident review ---------- */\nfunction initPostIncident(){\n  const btn = document.getElementById('postincident-generate'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const report = document.getElementById('postincident-report'); report.style.display='block';\n    report.textContent = `INCIDENT REPORT \u2014 Checkout Service Outage\n\nTimeline:\n  14:02  Alert fired: 502 errors on checkout API (30% of requests)\n  14:05  Investigation began \u2014 LB backend health checked first\n  14:11  Compute, network, security, storage, DNS ruled out\n  14:14  Root cause found: application crash-loop in payment-processing pod\n  14:22  Mitigation: rolled back the deploy that introduced the bug\n  14:26  Recovery confirmed \u2014 error rate back to baseline\n\nRoot Cause:\n  Unhandled null reference in the new discount-code feature, introduced\n  in a deploy 20 minutes before the incident.\n\nCorrective Action:\n  Rolled back to the previous stable deploy.\n\nPreventive Action:\n  Add null-check unit test coverage for discount-code paths;\n  require canary deployment with automated error-rate gating\n  before full rollout.\n\nLessons Learned:\n  Backend health checks correctly identified traffic WAS reaching\n  the backend, which should have pointed to the application layer\n  faster \u2014 update the runbook to check application logs earlier\n  when LB health looks fine but errors persist.`;\n  });\n}\n\n/* ---------- scenario design center ---------- */\nfunction initScenarioCenter(){\n  const cards = document.querySelectorAll('.scenario-card'); if(!cards.length) return;\n  const detail = document.getElementById('scenario-detail');\n  const scenarios = {\n    banking: '\ud83c\udfe6 Banking: \"Wire transfer API is timing out for international transfers only.\" Likely suspects: FastConnect to the SWIFT gateway, regional latency, or a backend timeout threshold too low for cross-border calls.',\n    healthcare: '\ud83c\udfe5 Healthcare: \"Patient records portal is down during business hours.\" Likely suspects: database connection pool exhaustion, an expired TLS certificate on the LB, or a botched compliance-driven firewall rule change.',\n    retail: '\ud83d\uded2 Retail: \"Checkout fails only during flash sale traffic spikes.\" Likely suspects: backend autoscaling not keeping pace, database connection limits, or LB backend set sized too small.',\n    manufacturing: '\ud83c\udfed Manufacturing: \"IoT sensor data stopped arriving from the factory floor.\" Likely suspects: Site-to-Site VPN tunnel down, on-prem CPE misconfiguration, or a route table missing the sensor subnet.',\n    government: '\ud83c\udfdb Government: \"Citizen portal inaccessible, compliance audit in 2 days.\" Likely suspects: a Security Zone policy blocking a needed change, IAM policy misconfiguration, or DNS propagation delay after a migration.'\n  };\n  cards.forEach(c=>{\n    c.addEventListener('click', ()=>{\n      detail.style.display='block';\n      detail.innerHTML = `<p>${scenarios[c.dataset.industry]}</p><p class=\"small mt-lg\">Apply the troubleshooting methodology from Module 1: Identify \u2192 Isolate \u2192 Diagnose \u2192 Resolve \u2192 Validate \u2192 Prevent.</p>`;\n    });\n  });\n}\n\n;\n\n/* ---------- flashcards 8 ---------- */\nfunction initFlashcards8(){\n  const wrap = document.getElementById('flash-wrap8'); if(!wrap) return;\n  const cards = [\n    ['6-step methodology','Identify, Isolate, Diagnose, Resolve, Validate, Prevent'],\n    ['5 Whys','Keep asking why until you reach the actual root cause'],\n    ['Serial Console','Raw text access to an instance \u2014 works with zero network connectivity'],\n    ['SSH timeout checklist','Key, user, NSG, Security List, route, public IP, cloud-init'],\n    ['IPSec tunnels per connection','2, for redundancy \u2014 one can fail over to the other'],\n    ['FastConnect','A dedicated private link bypassing the public internet entirely'],\n    ['502 vs 503 vs 504','502=bad backend response, 503=no healthy backend, 504=backend too slow'],\n    ['Asymmetric routing','Return traffic takes a different path than outbound \u2014 stateful firewalls drop it'],\n    ['NFS mount timeout','Check the mount target NSG/Security List for ports 2048-2050, 111 first'],\n    ['Flow logs','Show exactly which packets were accepted vs rejected, and why'],\n    ['Longest prefix match','The most specific matching route rule always wins'],\n    ['Postmortem','Should always include corrective AND preventive action, not just a fix'],\n  ];\n  wrap.innerHTML = cards.map(([f,b])=>`<div class=\"flashcard\"><div class=\"fc-inner\"><div class=\"fc-face fc-front\">${f}</div><div class=\"fc-face fc-back\">${b}</div></div></div>`).join('');\n  wrap.querySelectorAll('.flashcard').forEach(fc=> fc.addEventListener('click', ()=> fc.classList.toggle('flipped')));\n}\n\n/* ---------- certification quiz 8 ---------- */\nfunction initQuiz8(){\n  const wrap = document.getElementById('quiz-wrap8'); if(!wrap) return;\n  const Q = [\n    {q:'In the 6-step troubleshooting methodology, what comes immediately after \"Resolve\"?', o:['Prevent','Validate','Identify','Isolate'], c:1, e:'You must Validate the fix actually resolved the issue before moving to Prevent.'},\n    {q:'The \"5 Whys\" technique is used to:', o:['Assign blame quickly','Iteratively dig past symptoms to the actual root cause','Replace all monitoring dashboards','Automatically generate fixes'], c:1, e:'Repeatedly asking \"why\" surfaces the root cause rather than stopping at the first symptom.'},\n    {q:'An instance is completely unreachable over the network. What tool lets you access it anyway?', o:['Bastion','Serial Console','Load Balancer','Flow Logs'], c:1, e:'Serial Console gives raw text access to an instance with zero dependency on network connectivity.'},\n    {q:'SSH \"Connection timed out\" (not \"Permission denied\") most likely points to:', o:['Wrong SSH key','A network-level block (NSG, Security List, or route)','Wrong username','Cloud-init failure'], c:1, e:'A timeout (vs an explicit rejection) is characteristic of packets being silently dropped at the network layer.'},\n    {q:'Why does a Site-to-Site VPN connection create 2 IPSec tunnels?', o:['To double the bandwidth','For redundancy \u2014 if one fails, traffic uses the other', 'It is a billing requirement', 'To support two different VCNs'], c:1, e:'The second tunnel exists purely for failover redundancy.'},\n    {q:'What is the primary advantage of FastConnect over Site-to-Site VPN?', o:['It is always cheaper','A dedicated private connection with more predictable performance, bypassing the public internet', 'It requires no configuration', 'It works without a DRG'], c:1, e:'FastConnect provides a dedicated physical link with more consistent latency/throughput than internet-routed VPN.'},\n    {q:'A BGP peer shows state \"Idle\". What does this indicate?', o:['The session is healthy and passing routes','The BGP session has not been established', 'Routes are being filtered only', 'This is a normal steady state'], c:1, e:'\"Idle\" means the BGP session isn\\'t even attempting to connect properly \u2014 the earliest, most broken state.'},\n    {q:'Two route rules match a destination \u2014 a /16 and a /24. Which one is used?', o:['The /16, because it was created first','The /24, because it is more specific (longest prefix match)', 'Both are used simultaneously', 'Neither \u2014 this is a routing conflict error'], c:1, e:'OCI route tables use longest-prefix-match, so the more specific /24 wins.'},\n    {q:'VCN Flow Logs are most useful for:', o:['Measuring CPU usage','Seeing exactly which packets were accepted or rejected, and why', 'Rotating encryption keys', 'Creating backups'], c:1, e:'Flow logs record accept/reject decisions at the network level, invaluable for diagnosing blocked traffic.'},\n    {q:'A load balancer returns 503 Service Unavailable. This most directly means:', o:['The backend took too long to respond','No healthy backends are currently available in the backend set', 'The client sent a malformed request', 'The SSL certificate expired'], c:1, e:'503 specifically indicates the LB has no healthy backend to route the request to.'},\n    {q:'A load balancer returns 504 Gateway Timeout. This most directly means:', o:['No backends exist','The backend exists and is healthy, but didn\\'t respond within the timeout window', 'The client is unauthorized', 'DNS failed to resolve'], c:1, e:'504 means a backend was reached but was too slow to respond in time.'},\n    {q:'A backend is marked \"unhealthy\" by the load balancer\\'s health check. What should NOT be your first assumption?', o:['The application itself is definitely down','The firewall/NSG might be blocking just the health check port', 'The health check might be using the wrong path/port', 'DNS resolution for the backend might be failing'], c:0, e:'Many \"unhealthy\" backends are actually healthy applications blocked by a firewall or misconfigured health check \u2014 don\\'t assume the app is broken first.'},\n    {q:'Asymmetric routing commonly breaks connectivity because:', o:['It uses too much bandwidth','Stateful firewalls only recognize traffic that traverses them in both directions, and drop the \"unrecognized\" return path', 'DNS caches become corrupted', 'It doubles latency only'], c:1, e:'A stateful firewall that only sees one direction of a flow will treat the return traffic as unsolicited and drop it.'},\n    {q:'An NFS mount times out. What should you check first?', o:['The object storage bucket policy','The mount target\\'s NSG/Security List for NFS ports (2048-2050, 111)', 'The compute instance\\'s CPU usage', 'The VCN\\'s DNS label'], c:1, e:'NFS mount timeouts are most commonly a network-layer block on the required NFS ports.'},\n    {q:'iostat shows a volume at 98% utilization with high write latency. What does this suggest?', o:['The volume is idle','The volume is I/O-saturated for its current performance tier', 'The instance has a memory leak', 'The network is misconfigured'], c:1, e:'High utilization plus high latency together point to the disk itself being the bottleneck.'},\n    {q:'A production outage investigation rules out compute, network, security, storage, and DNS \u2014 the load balancer shows all backends healthy. Where should you look next?', o:['Nowhere \u2014 the outage must be a false alarm','The application layer itself (code, recent deploys, dependencies)', 'Re-check compute again', 'The physical data center'], c:1, e:'If traffic is reaching healthy backends but the service still fails, the application layer is the remaining suspect.'},\n    {q:'A postmortem/incident report should always include:', o:['Only the timeline','Root cause plus both corrective AND preventive action', 'Only who was on call', 'Just a summary with no timeline'], c:1, e:'A complete postmortem addresses both fixing the immediate problem and preventing recurrence.'},\n    {q:'What is the key difference between Run Commands and SSH for remote diagnostics?', o:['Run Commands require SSH to already be working','Run Commands execute without needing SSH access at all', 'They are identical features with different names', 'Run Commands only work on Windows instances'], c:1, e:'Run Commands operate independently of SSH connectivity \u2014 useful precisely when SSH itself is the problem.'},\n    {q:'A CPE\\'s IKE Phase 1 fails to establish against OCI. What is a common cause?', o:['Wrong boot volume size','A mismatched pre-shared key between the CPE and the OCI IPSec configuration', 'An expired TLS certificate', 'A missing NSG rule for port 443'], c:1, e:'Phase 1 (IKE) commonly fails due to a pre-shared key mismatch between the two ends.'},\n    {q:'Which OSI-layer-based approach helps most when troubleshooting \"can\\'t reach the app server\"?', o:['Randomly restarting services until it works','Working systematically bottom-up (or top-down) through the OSI layers to isolate where the failure occurs', 'Only checking the application logs', 'Assuming it is always a DNS issue'], c:1, e:'Layer-by-layer diagnosis narrows down the failing component methodically instead of guessing.'},\n  ];\n  state.quizTotal = Q.length;\n  wrap.innerHTML = Q.map((item,qi)=>`\n    <div class=\"quiz-q\" id=\"quiz8-${qi}\">\n      <div class=\"qtext\">${qi+1}. ${item.q}</div>\n      <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"q8-${qi}\" value=\"${oi}\"> ${opt}</label>`).join('')}</div>\n      <div class=\"quiz-explain\">${item.e}</div>\n    </div>`).join('');\n  wrap.querySelectorAll('.quiz-q').forEach((qEl, qi)=>{\n    qEl.addEventListener('change', e=>{\n      if(qEl.classList.contains('answered')) return;\n      qEl.classList.add('answered');\n      const chosen = parseInt(e.target.value);\n      qEl.querySelectorAll('.quiz-opt').forEach((o,oi)=>{ if(oi===Q[qi].c) o.classList.add('correct'); else if(oi===chosen) o.classList.add('incorrect'); });\n      state.quizAnswered++; if(chosen===Q[qi].c) state.quizScore++;\n      document.getElementById('score-chip-val').textContent = `${state.quizScore} / ${state.quizAnswered}`;\n      document.getElementById('quiz-final-score8').textContent = `${state.quizScore} / ${Q.length}`;\n      document.getElementById('cert-score-display8').textContent = `${state.quizScore}/${Q.length}`;\n      updateBadge8();\n    });\n  });\n}\n\n/* ---------- badge / certificate 8 ---------- */\nfunction updateBadge8(){\n  const scrollPct = window.__lastScrollPct8 || 0;\n  const quizPct = state.quizTotal ? (state.quizAnswered/state.quizTotal)*100 : 0;\n  const combined = Math.round(scrollPct*0.5 + quizPct*0.5);\n  const circle = document.getElementById('badge-circle8'); if(!circle) return;\n  circle.style.setProperty('--pct', (combined*3.6)+'deg');\n  document.getElementById('badge-pct8').textContent = combined+'%';\n  const title = document.getElementById('badge-title8'); const sub = document.getElementById('badge-sub8');\n  if(combined>=95){ title.textContent='\ud83c\udfc6 Day 8 Complete'; sub.textContent='Certificate preview unlocked below.'; }\n  else if(combined>=50){ title.textContent='\ud83d\udfe0 Halfway there'; sub.textContent='Keep going through the remaining sections and the quiz.'; }\n  else { title.textContent='Keep going'; sub.textContent='Complete every section and the quiz to preview your certificate.'; }\n  const d = new Date(); document.getElementById('cert-date-display8').textContent = d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});\n}\n"};
